insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000001', 'en', 'Giftun Island snorkelling day', 'Two reef stops, a beach on Giftun Island and lunch on board.', 'A relaxed full day on the water. The boat leaves Hurghada marina in the morning and anchors at two reefs inside the Giftun protected area, where the crew shows you the best spots for coral and fish. Between the snorkel stops you spend time on the white beach of Giftun Island.
Snorkelling gear and a buoyancy vest are provided; the crew stays with beginners in the water.', '08:30 pickup from your hotel (if booked)
09:30 boat leaves the marina
10:30 first reef stop: snorkelling
12:00 Giftun Island beach time
13:30 lunch on board
14:30 second reef stop
16:00 back at the marina', 'Boat trip with crew
Snorkelling mask, fins and vest
Lunch on board, water and soft drinks
Protected-area fee', 'Hotel transfer (optional add-on)
Towels
Tips', 'Bring sunscreen that is safe for reefs, a towel and a hat.
Not recommended for people who cannot swim at all; vests are available.', 'Hurghada New Marina, gate 2. Look for the WENRO sign at the pier 20 minutes before departure.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000001', 'ar', 'رحلة سنوركل جزيرة الجفتون', 'محطتان على الشعاب، وشاطئ جزيرة الجفتون، وغداء على المركب.', 'يوم كامل هادئ في البحر. يغادر المركب مارينا الغردقة صباحًا ويرسو عند شعبتين داخل محمية الجفتون، ويوضح لك الطاقم أفضل الأماكن لمشاهدة الشعاب والأسماك. وبين محطات السنوركل تقضي وقتًا على شاطئ الجزيرة الأبيض.
معدات السنوركل وسترة الطفو متوفرة، ويبقى الطاقم مع المبتدئين في الماء.', '08:30 الاستلام من الفندق (إن تم حجز التوصيل)
09:30 تحرك المركب من المارينا
10:30 الشعبة الأولى: سنوركل
12:00 وقت على شاطئ الجفتون
13:30 الغداء على المركب
14:30 الشعبة الثانية
16:00 العودة إلى المارينا', 'رحلة المركب مع الطاقم
قناع السنوركل والزعانف والسترة
غداء على المركب ومياه ومشروبات غازية
رسوم المحمية', 'التوصيل من الفندق (إضافة اختيارية)
المناشف
الإكراميات', 'أحضر واقي شمس آمن للشعاب ومنشفة وقبعة.
غير مناسبة لمن لا يجيد السباحة إطلاقًا؛ السترات متوفرة.', 'مارينا الغردقة الجديدة، البوابة 2. ابحث عن لافتة WENRO على الرصيف قبل الموعد بـ 20 دقيقة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000001', 'de', 'Schnorcheltag auf der Insel Giftun', 'Zwei Riffstopps, ein Strand auf der Insel Giftun und Mittagessen an Bord.', 'Ein entspannter ganzer Tag auf dem Wasser. Das Boot verlässt morgens die Marina von Hurghada und ankert an zwei Riffen im Schutzgebiet Giftun, wo die Crew Ihnen die besten Stellen für Korallen und Fische zeigt. Zwischen den Schnorchelstopps verbringen Sie Zeit am weißen Strand der Insel Giftun.
Schnorchelausrüstung und eine Auftriebsweste werden gestellt; die Crew bleibt bei Anfängern im Wasser.', '08:30 Abholung vom Hotel (falls gebucht)
09:30 Das Boot verlässt die Marina
10:30 Erster Riffstopp: Schnorcheln
12:00 Strandzeit auf der Insel Giftun
13:30 Mittagessen an Bord
14:30 Zweiter Riffstopp
16:00 Zurück an der Marina', 'Bootsfahrt mit Crew
Schnorchelmaske, Flossen und Weste
Mittagessen an Bord, Wasser und Softdrinks
Gebühr für das Schutzgebiet', 'Hoteltransfer (optional zubuchbar)
Handtücher
Trinkgelder', 'Bringen Sie riffschonende Sonnencreme, ein Handtuch und eine Kopfbedeckung mit.
Nicht empfohlen für Personen, die gar nicht schwimmen können; Westen sind vorhanden.', 'Hurghada New Marina, Tor 2. Halten Sie 20 Minuten vor Abfahrt am Anleger nach dem WENRO-Schild Ausschau.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000001', 'ru', 'Снорклинг на острове Гифтун', 'Две остановки на рифах, пляж на острове Гифтун и обед на борту.', 'Расслабленный день на воде. Утром лодка выходит из марины Хургады и встаёт на якорь у двух рифов в заповедной зоне Гифтун, где команда покажет вам лучшие места с кораллами и рыбами. Между остановками для снорклинга вы отдыхаете на белом пляже острова Гифтун.
Снаряжение для снорклинга и жилет предоставляются; команда остаётся в воде рядом с новичками.', '08:30 трансфер из отеля (если забронирован)
09:30 отправление лодки из марины
10:30 первая остановка на рифе: снорклинг
12:00 время на пляже острова Гифтун
13:30 обед на борту
14:30 вторая остановка на рифе
16:00 возвращение в марину', 'Морская прогулка с командой
Маска, ласты и жилет для снорклинга
Обед на борту, вода и безалкогольные напитки
Сбор за посещение заповедной зоны', 'Трансфер из отеля (дополнительная опция)
Полотенца
Чаевые', 'Возьмите солнцезащитный крем, безопасный для рифов, полотенце и головной убор.
Не рекомендуется тем, кто совсем не умеет плавать; есть жилеты.', 'Новая марина Хургады, ворота 2. Ищите табличку WENRO на причале за 20 минут до отправления.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000001', 'fr', 'Journée snorkeling à l’île de Giftun', 'Deux arrêts sur des récifs, une plage sur l’île de Giftun et le déjeuner à bord.', 'Une journée complète et détendue sur l’eau. Le bateau quitte la marina de Hurghada le matin et jette l’ancre sur deux récifs de la zone protégée de Giftun, où l’équipage vous montre les meilleurs spots pour les coraux et les poissons. Entre les arrêts snorkeling, vous profitez de la plage blanche de l’île de Giftun.
L’équipement de snorkeling et un gilet de flottabilité sont fournis ; l’équipage reste avec les débutants dans l’eau.', '08:30 prise en charge à votre hôtel (si réservée)
09:30 départ du bateau depuis la marina
10:30 premier arrêt sur un récif : snorkeling
12:00 temps libre sur la plage de l’île de Giftun
13:30 déjeuner à bord
14:30 deuxième arrêt sur un récif
16:00 retour à la marina', 'Sortie en bateau avec équipage
Masque, palmes et gilet de snorkeling
Déjeuner à bord, eau et boissons sans alcool
Droit d’accès à la zone protégée', 'Transfert depuis l’hôtel (option)
Serviettes
Pourboires', 'Apportez une crème solaire sans danger pour les récifs, une serviette et un chapeau.
Déconseillé aux personnes qui ne savent pas du tout nager ; des gilets sont disponibles.', 'Hurghada New Marina, porte 2. Repérez le panneau WENRO sur le ponton 20 minutes avant le départ.', false, true);
