insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000002', 'en', 'Quad ride to a Bedouin village', 'One hour on your own quad through the desert, tea in a Bedouin village.', 'After a short safety briefing you ride your own quad in a guided line across open desert tracks. Halfway you stop at a Bedouin village for tea and bread baked on the fire, and a short camel walk.
The operator confirms your request within 12 hours because riders and helmets are assigned in advance.', 'Safety briefing and helmet fitting
1 hour quad ride with a guide in front and behind
Bedouin village: tea, bread, short camel walk
Ride back to camp', 'Quad bike and fuel
Helmet, goggles and scarf
Guide
Bedouin tea and bread', 'Hotel transfer (optional add-on)
Photos sold at the camp', 'Minimum age 16 to drive. Closed shoes recommended.
Not suitable during pregnancy or with back problems.', 'Desert camp on the Hurghada–Safaga road. Exact pin is sent with your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000002', 'ar', 'جولة بالموتوسيكل الرباعي إلى قرية بدوية', 'ساعة على موتوسيكل رباعي خاص بك في الصحراء، وشاي في قرية بدوية.', 'بعد شرح قصير للسلامة تقود موتوسيكلك الرباعي في صف مع المرشد عبر مسارات الصحراء المفتوحة. وفي منتصف الطريق تتوقف في قرية بدوية لتناول الشاي والخبز المخبوز على النار، وجولة قصيرة على الجمل.
يؤكد المشغّل طلبك خلال 12 ساعة لأن الموتوسيكلات والخوذ تُحجز مسبقًا.', 'شرح السلامة وتجهيز الخوذة
ساعة قيادة مع مرشد في المقدمة والمؤخرة
القرية البدوية: شاي وخبز وجولة قصيرة على الجمل
العودة إلى المعسكر', 'الموتوسيكل الرباعي والوقود
خوذة ونظارة وشال
مرشد
شاي وخبز بدوي', 'التوصيل من الفندق (إضافة اختيارية)
الصور المباعة في المعسكر', 'الحد الأدنى للسن 16 عامًا للقيادة. يُفضل حذاء مغلق.
غير مناسبة أثناء الحمل أو لمن يعاني من مشاكل في الظهر.', 'معسكر الصحراء على طريق الغردقة–سفاجا. الموقع الدقيق يصلك مع القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000002', 'de', 'Quadtour zu einem Beduinendorf', 'Eine Stunde auf Ihrem eigenen Quad durch die Wüste, Tee in einem Beduinendorf.', 'Nach einer kurzen Sicherheitseinweisung fahren Sie Ihr eigenes Quad in einer geführten Kolonne über offene Wüstenpisten. Auf halber Strecke halten Sie in einem Beduinendorf für Tee und über dem Feuer gebackenes Brot sowie einen kurzen Kamelritt.
Der Anbieter bestätigt Ihre Anfrage innerhalb von 12 Stunden, da Fahrer und Helme im Voraus zugeteilt werden.', 'Sicherheitseinweisung und Anpassen des Helms
1 Stunde Quadfahrt mit Guide vorne und hinten
Beduinendorf: Tee, Brot, kurzer Kamelritt
Rückfahrt zum Camp', 'Quad und Treibstoff
Helm, Brille und Tuch
Guide
Beduinentee und Brot', 'Hoteltransfer (optional zubuchbar)
Im Camp verkaufte Fotos', 'Mindestalter 16 Jahre zum Selbstfahren. Geschlossene Schuhe empfohlen.
Nicht geeignet während der Schwangerschaft oder bei Rückenproblemen.', 'Wüstencamp an der Straße Hurghada–Safaga. Der genaue Standort-Pin kommt mit Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000002', 'ru', 'Поездка на квадроцикле в бедуинскую деревню', 'Час на собственном квадроцикле по пустыне и чай в бедуинской деревне.', 'После короткого инструктажа по безопасности вы едете на собственном квадроцикле в колонне за гидом по открытым пустынным трассам. На полпути — остановка в бедуинской деревне: чай, лепёшки, испечённые на огне, и короткая прогулка на верблюде.
Оператор подтверждает вашу заявку в течение 12 часов, потому что квадроциклы и шлемы распределяются заранее.', 'Инструктаж по безопасности и подбор шлема
1 час на квадроцикле с гидом впереди и позади колонны
Бедуинская деревня: чай, лепёшки, короткая прогулка на верблюде
Возвращение в лагерь', 'Квадроцикл и топливо
Шлем, очки и платок
Гид
Бедуинский чай и лепёшки', 'Трансфер из отеля (дополнительная опция)
Фотографии, которые продаются в лагере', 'Управлять квадроциклом можно с 16 лет. Рекомендуется закрытая обувь.
Не подходит при беременности и проблемах со спиной.', 'Лагерь в пустыне на трассе Хургада — Сафага. Точная точка на карте придёт вместе с ваучером.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000002', 'fr', 'Quad jusqu’à un village bédouin', 'Une heure sur votre propre quad à travers le désert, thé dans un village bédouin.', 'Après un court briefing sécurité, vous conduisez votre propre quad en file guidée sur des pistes ouvertes du désert. À mi-parcours, vous faites halte dans un village bédouin pour un thé, du pain cuit au feu de bois et une courte balade à dos de chameau.
Le prestataire confirme votre demande sous 12 heures, car les pilotes et les casques sont attribués à l’avance.', 'Briefing sécurité et réglage du casque
1 heure de quad avec un guide devant et un derrière
Village bédouin : thé, pain, courte balade à dos de chameau
Retour au camp', 'Quad et carburant
Casque, lunettes et foulard
Guide
Thé et pain bédouins', 'Transfert depuis l’hôtel (option)
Photos vendues au camp', 'Âge minimum pour conduire : 16 ans. Chaussures fermées recommandées.
Déconseillé pendant la grossesse ou en cas de problèmes de dos.', 'Camp dans le désert sur la route Hurghada–Safaga. La localisation exacte est envoyée avec votre bon.', false, true);
