insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000003', 'en', 'Dolphin House by speedboat', 'A fast boat to the reef where spinner dolphins often rest, with two snorkel stops.', 'Dolphin House is a horseshoe reef where wild spinner dolphins often come to rest. The crew keeps a respectful distance and follows the local code of conduct: no chasing, no feeding, no touching.
Dolphins are wild animals, so sightings are likely but never guaranteed. The second stop is a coral garden for snorkelling.', '08:00 boat leaves the marina
09:15 Dolphin House: watch and snorkel with care
11:30 coral garden snorkel stop
12:30 lunch on board
14:00 back at the marina', 'Speedboat with crew
Snorkelling gear
Lunch, water and soft drinks', 'Hotel transfer (optional add-on)
Tips', 'Sea can be choppy; tell the crew if you get seasick.
Children must wear a vest in the water.', 'Hurghada New Marina, gate 2, 20 minutes before departure.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000003', 'ar', 'بيت الدلافين بالمركب السريع', 'مركب سريع إلى الشعبة التي تستريح فيها الدلافين غالبًا، مع محطتين للسنوركل.', 'بيت الدلافين شعبة على شكل حدوة حصان تأتي إليها الدلافين البرية للراحة غالبًا. يلتزم الطاقم بمسافة محترمة وبقواعد السلوك المحلية: لا مطاردة ولا إطعام ولا لمس.
الدلافين حيوانات برية، لذلك رؤيتها مرجحة لكنها غير مضمونة. المحطة الثانية حديقة شعاب للسنوركل.', '08:00 تحرك المركب من المارينا
09:15 بيت الدلافين: مشاهدة وسنوركل بهدوء
11:30 محطة سنوركل عند الشعاب
12:30 الغداء على المركب
14:00 العودة إلى المارينا', 'مركب سريع مع الطاقم
معدات السنوركل
غداء ومياه ومشروبات غازية', 'التوصيل من الفندق (إضافة اختيارية)
الإكراميات', 'البحر قد يكون متقلبًا؛ أخبر الطاقم إن كنت تعاني من دوار البحر.
يرتدي الأطفال السترة في الماء.', 'مارينا الغردقة الجديدة، البوابة 2، قبل الموعد بـ 20 دقيقة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000003', 'de', 'Dolphin House mit dem Schnellboot', 'Mit einem schnellen Boot zum Riff, an dem Spinnerdelfine oft rasten, mit zwei Schnorchelstopps.', 'Dolphin House ist ein hufeisenförmiges Riff, an dem wilde Spinnerdelfine oft zum Ausruhen kommen. Die Crew hält respektvollen Abstand und befolgt die örtlichen Verhaltensregeln: nicht verfolgen, nicht füttern, nicht berühren.
Delfine sind Wildtiere, daher sind Sichtungen wahrscheinlich, aber nie garantiert. Der zweite Stopp ist ein Korallengarten zum Schnorcheln.', '08:00 Das Boot verlässt die Marina
09:15 Dolphin House: rücksichtsvoll beobachten und schnorcheln
11:30 Schnorchelstopp am Korallengarten
12:30 Mittagessen an Bord
14:00 Zurück an der Marina', 'Schnellboot mit Crew
Schnorchelausrüstung
Mittagessen, Wasser und Softdrinks', 'Hoteltransfer (optional zubuchbar)
Trinkgelder', 'Das Meer kann unruhig sein; sagen Sie der Crew Bescheid, wenn Sie seekrank werden.
Kinder müssen im Wasser eine Weste tragen.', 'Hurghada New Marina, Tor 2, 20 Minuten vor Abfahrt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000003', 'ru', 'Дом дельфинов на скоростном катере', 'Быстрый катер к рифу, где часто отдыхают дельфины-вертуны, и две остановки для снорклинга.', 'Дом дельфинов — риф в форме подковы, куда дикие дельфины-вертуны часто приплывают отдохнуть. Команда держит уважительную дистанцию и соблюдает местные правила поведения: не преследовать, не кормить, не трогать.
Дельфины — дикие животные, поэтому встретить их вероятно, но никогда не гарантировано. Вторая остановка — коралловый сад для снорклинга.', '08:00 отправление лодки из марины
09:15 Дом дельфинов: наблюдение и бережный снорклинг
11:30 остановка для снорклинга в коралловом саду
12:30 обед на борту
14:00 возвращение в марину', 'Скоростной катер с командой
Снаряжение для снорклинга
Обед, вода и безалкогольные напитки', 'Трансфер из отеля (дополнительная опция)
Чаевые', 'Море может быть неспокойным; сообщите команде, если вас укачивает.
Дети должны быть в воде в жилете.', 'Новая марина Хургады, ворота 2, за 20 минут до отправления.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000003', 'fr', 'Dolphin House en bateau rapide', 'Un bateau rapide jusqu’au récif où les dauphins à long bec viennent souvent se reposer, avec deux arrêts snorkeling.', 'Dolphin House est un récif en fer à cheval où des dauphins à long bec sauvages viennent souvent se reposer. L’équipage garde une distance respectueuse et suit le code de conduite local : pas de poursuite, pas de nourriture, pas de contact.
Les dauphins sont des animaux sauvages : les observations sont probables mais jamais garanties. Le deuxième arrêt est un jardin de corail pour le snorkeling.', '08:00 départ du bateau depuis la marina
09:15 Dolphin House : observation et snorkeling dans le respect des animaux
11:30 arrêt snorkeling au jardin de corail
12:30 déjeuner à bord
14:00 retour à la marina', 'Bateau rapide avec équipage
Équipement de snorkeling
Déjeuner, eau et boissons sans alcool', 'Transfert depuis l’hôtel (option)
Pourboires', 'La mer peut être agitée ; prévenez l’équipage si vous avez le mal de mer.
Les enfants doivent porter un gilet dans l’eau.', 'Hurghada New Marina, porte 2, 20 minutes avant le départ.', false, true);
