insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000004', 'en', 'Orange Bay beach day', 'A long beach stop on a white-sand bay, one snorkel stop and lunch.', 'A slow day built around the beach. Most of the time is spent on a white-sand bay with shallow turquoise water, good for families and non-swimmers. One snorkel stop on the way back.', '09:00 boat leaves the marina
10:30 arrival at the bay: free beach time
13:00 lunch
14:30 snorkel stop
16:30 back at the marina', 'Boat trip
Beach entrance
Lunch and soft drinks
Snorkelling gear', 'Hotel transfer (optional add-on)
Loungers (optional extra)', 'Bring a towel and reef-safe sunscreen.', 'Hurghada New Marina, gate 2, 20 minutes before departure.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000004', 'ar', 'يوم على شاطئ أورانج باي', 'وقت طويل على خليج رمله أبيض، ومحطة سنوركل واحدة وغداء.', 'يوم هادئ يدور حول الشاطئ. معظم الوقت على خليج رمله أبيض ومياهه فيروزية ضحلة، مناسب للعائلات ومن لا يسبح. ومحطة سنوركل واحدة في طريق العودة.', '09:00 تحرك المركب من المارينا
10:30 الوصول للخليج: وقت حر على الشاطئ
13:00 الغداء
14:30 محطة سنوركل
16:30 العودة إلى المارينا', 'رحلة المركب
دخول الشاطئ
غداء ومشروبات غازية
معدات السنوركل', 'التوصيل من الفندق (إضافة اختيارية)
الشيزلونج (إضافة اختيارية)', 'أحضر منشفة وواقي شمس آمن للشعاب.', 'مارينا الغردقة الجديدة، البوابة 2، قبل الموعد بـ 20 دقيقة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000004', 'de', 'Strandtag in der Orange Bay', 'Ein langer Strandaufenthalt in einer Bucht mit weißem Sand, ein Schnorchelstopp und Mittagessen.', 'Ein entspannter Tag rund um den Strand. Die meiste Zeit verbringen Sie in einer Bucht mit weißem Sand und flachem, türkisfarbenem Wasser – gut für Familien und Nichtschwimmer. Auf dem Rückweg gibt es einen Schnorchelstopp.', '09:00 Das Boot verlässt die Marina
10:30 Ankunft in der Bucht: freie Zeit am Strand
13:00 Mittagessen
14:30 Schnorchelstopp
16:30 Zurück an der Marina', 'Bootsfahrt
Strandeintritt
Mittagessen und Softdrinks
Schnorchelausrüstung', 'Hoteltransfer (optional zubuchbar)
Liegen (optional gegen Aufpreis)', 'Bringen Sie ein Handtuch und riffschonende Sonnencreme mit.', 'Hurghada New Marina, Tor 2, 20 Minuten vor Abfahrt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000004', 'ru', 'Пляжный день в Orange Bay', 'Долгая остановка на пляже в бухте с белым песком, одна остановка для снорклинга и обед.', 'Неспешный день, построенный вокруг пляжа. Большую часть времени вы проводите в бухте с белым песком и мелкой бирюзовой водой — отлично подходит для семей и тех, кто не умеет плавать. На обратном пути — одна остановка для снорклинга.', '09:00 отправление лодки из марины
10:30 прибытие в бухту: свободное время на пляже
13:00 обед
14:30 остановка для снорклинга
16:30 возвращение в марину', 'Морская прогулка
Вход на пляж
Обед и безалкогольные напитки
Снаряжение для снорклинга', 'Трансфер из отеля (дополнительная опция)
Лежаки (за доплату)', 'Возьмите полотенце и солнцезащитный крем, безопасный для рифов.', 'Новая марина Хургады, ворота 2, за 20 минут до отправления.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000004', 'fr', 'Journée plage à Orange Bay', 'Une longue pause sur une baie de sable blanc, un arrêt snorkeling et le déjeuner.', 'Une journée tranquille centrée sur la plage. Vous passez l’essentiel du temps dans une baie de sable blanc aux eaux turquoise peu profondes, idéale pour les familles et les personnes qui ne nagent pas. Un arrêt snorkeling sur le chemin du retour.', '09:00 départ du bateau depuis la marina
10:30 arrivée dans la baie : temps libre à la plage
13:00 déjeuner
14:30 arrêt snorkeling
16:30 retour à la marina', 'Sortie en bateau
Entrée à la plage
Déjeuner et boissons sans alcool
Équipement de snorkeling', 'Transfert depuis l’hôtel (option)
Transats (en supplément)', 'Apportez une serviette et une crème solaire sans danger pour les récifs.', 'Hurghada New Marina, porte 2, 20 minutes avant le départ.', false, true);
