insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000005', 'en', 'Discover scuba: your first dive', 'No experience needed: training in shallow water, then a guided dive to 6–12 m.', 'A first taste of diving with a licensed instructor, one instructor for every two guests. You learn the basics in shallow water first; only when you feel ready do you go down to a calm reef.
You fill in a short medical questionnaire before the trip.', '08:30 meet at the dive centre
09:00 briefing and equipment fitting
10:30 shallow-water practice
11:30 guided dive (about 30 minutes)
13:00 back on land', 'All diving equipment
Instructor (1 for 2 guests)
Boat trip, water and snacks', 'Hotel transfer (optional add-on)
Dive photos', 'Minimum age 10. Medical questionnaire required.
No flying within 24 hours after diving.', 'Dive centre, Sheraton Road. Pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000005', 'ar', 'تجربة الغوص الأولى', 'بدون خبرة سابقة: تدريب في مياه ضحلة ثم غطسة مع مدرب إلى عمق 6–12 مترًا.', 'تجربة أولى للغوص مع مدرب مرخّص، مدرب لكل ضيفين. تتعلم الأساسيات في المياه الضحلة أولًا، ولا تنزل إلى الشعبة الهادئة إلا عندما تشعر بالاستعداد.
تملأ استبيانًا طبيًا قصيرًا قبل الرحلة.', '08:30 اللقاء في مركز الغوص
09:00 الشرح وتجهيز المعدات
10:30 تدريب في المياه الضحلة
11:30 غطسة مع المدرب (حوالي 30 دقيقة)
13:00 العودة إلى البر', 'كل معدات الغوص
مدرب (واحد لكل ضيفين)
رحلة المركب ومياه ووجبة خفيفة', 'التوصيل من الفندق (إضافة اختيارية)
صور الغوص', 'الحد الأدنى للسن 10 سنوات. الاستبيان الطبي مطلوب.
ممنوع الطيران خلال 24 ساعة بعد الغوص.', 'مركز الغوص، طريق الشيراتون. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000005', 'de', 'Schnuppertauchen: Ihr erster Tauchgang', 'Keine Erfahrung nötig: Übungen im flachen Wasser, danach ein geführter Tauchgang auf 6–12 m.', 'Ein erster Eindruck vom Tauchen mit einem lizenzierten Instruktor – ein Instruktor für je zwei Gäste. Zuerst lernen Sie die Grundlagen im flachen Wasser; erst wenn Sie sich bereit fühlen, geht es hinab an ein ruhiges Riff.
Vor dem Ausflug füllen Sie einen kurzen medizinischen Fragebogen aus.', '08:30 Treffen im Tauchzentrum
09:00 Briefing und Anpassen der Ausrüstung
10:30 Übungen im flachen Wasser
11:30 Geführter Tauchgang (etwa 30 Minuten)
13:00 Zurück an Land', 'Komplette Tauchausrüstung
Instruktor (1 für 2 Gäste)
Bootsfahrt, Wasser und Snacks', 'Hoteltransfer (optional zubuchbar)
Tauchfotos', 'Mindestalter 10 Jahre. Medizinischer Fragebogen erforderlich.
Kein Fliegen innerhalb von 24 Stunden nach dem Tauchen.', 'Tauchzentrum, Sheraton Road. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000005', 'ru', 'Пробный дайвинг: ваше первое погружение', 'Опыт не нужен: тренировка на мелководье, а затем погружение с гидом на 6–12 м.', 'Первое знакомство с дайвингом с лицензированным инструктором — один инструктор на каждых двух гостей. Сначала вы осваиваете основы на мелководье и только когда почувствуете себя готовыми, опускаетесь к спокойному рифу.
Перед поездкой вы заполняете короткую медицинскую анкету.', '08:30 встреча в дайвинг-центре
09:00 брифинг и подбор снаряжения
10:30 тренировка на мелководье
11:30 погружение с гидом (около 30 минут)
13:00 возвращение на берег', 'Всё снаряжение для дайвинга
Инструктор (1 на 2 гостей)
Морская прогулка, вода и закуски', 'Трансфер из отеля (дополнительная опция)
Фотографии с погружения', 'Минимальный возраст — 10 лет. Обязательна медицинская анкета.
Нельзя летать в течение 24 часов после погружения.', 'Дайвинг-центр, улица Шератон. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000005', 'fr', 'Baptême de plongée : votre première plongée', 'Aucune expérience requise : entraînement en eau peu profonde, puis plongée guidée entre 6 et 12 m.', 'Un premier aperçu de la plongée avec un moniteur diplômé, un moniteur pour deux participants. Vous apprenez d’abord les bases en eau peu profonde ; ce n’est que lorsque vous vous sentez prêt que vous descendez sur un récif calme.
Vous remplissez un court questionnaire médical avant la sortie.', '08:30 rendez-vous au centre de plongée
09:00 briefing et réglage de l’équipement
10:30 exercices en eau peu profonde
11:30 plongée guidée (environ 30 minutes)
13:00 retour à terre', 'Tout l’équipement de plongée
Moniteur (1 pour 2 participants)
Sortie en bateau, eau et en-cas', 'Transfert depuis l’hôtel (option)
Photos de plongée', 'Âge minimum : 10 ans. Questionnaire médical obligatoire.
Pas de vol en avion dans les 24 heures suivant la plongée.', 'Centre de plongée, Sheraton Road. Localisation sur votre bon.', false, true);
