insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000006', 'en', 'Glass-bottom boat: reefs without getting wet', 'Two hours watching coral and fish through the boat''s glass floor.', 'The easiest way to see the Red Sea reefs: sit in the lower deck and watch coral and fish through large glass windows. Good for small children, grandparents and anyone who prefers to stay dry.', 'Departure from the marina
Slow cruise over two reefs
Short stop to feed nothing and touch nothing: just watch
Return to the marina', 'Boat trip
Water', 'Hotel transfer (optional add-on)', 'Suitable for all ages.', 'Hurghada New Marina, gate 1, 15 minutes before departure.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000006', 'ar', 'المركب الزجاجي: الشعاب بدون ما تتبل', 'ساعتان لمشاهدة الشعاب والأسماك من أرضية المركب الزجاجية.', 'أسهل طريقة لرؤية شعاب البحر الأحمر: تجلس في الطابق السفلي وتشاهد الشعاب والأسماك من نوافذ زجاجية كبيرة. مناسب للأطفال الصغار وكبار السن ولمن يفضل عدم النزول للماء.', 'التحرك من المارينا
جولة بطيئة فوق شعبتين
توقف قصير للمشاهدة فقط بدون لمس أو إطعام
العودة إلى المارينا', 'رحلة المركب
مياه', 'التوصيل من الفندق (إضافة اختيارية)', 'مناسب لكل الأعمار.', 'مارينا الغردقة الجديدة، البوابة 1، قبل الموعد بـ 15 دقيقة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000006', 'de', 'Glasbodenboot: Riffe sehen, ohne nass zu werden', 'Zwei Stunden Korallen und Fische durch den Glasboden des Bootes beobachten.', 'Die einfachste Art, die Riffe des Roten Meeres zu sehen: Setzen Sie sich aufs Unterdeck und beobachten Sie Korallen und Fische durch große Glasfenster. Ideal für kleine Kinder, Großeltern und alle, die lieber trocken bleiben.', 'Abfahrt von der Marina
Langsame Fahrt über zwei Riffe
Kurzer Stopp – nichts füttern, nichts berühren: einfach zuschauen
Rückkehr zur Marina', 'Bootsfahrt
Wasser', 'Hoteltransfer (optional zubuchbar)', 'Für alle Altersgruppen geeignet.', 'Hurghada New Marina, Tor 1, 15 Minuten vor Abfahrt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000006', 'ru', 'Лодка со стеклянным дном: рифы, не намокнув', 'Два часа наблюдения за кораллами и рыбами через стеклянное дно лодки.', 'Самый простой способ увидеть рифы Красного моря: садитесь на нижней палубе и наблюдайте за кораллами и рыбами через большие стеклянные окна. Подходит для маленьких детей, бабушек и дедушек и всех, кто предпочитает оставаться сухим.', 'Отправление из марины
Неспешная прогулка над двумя рифами
Короткая остановка: ничего не кормим и ничего не трогаем — просто смотрим
Возвращение в марину', 'Морская прогулка
Вода', 'Трансфер из отеля (дополнительная опция)', 'Подходит для любого возраста.', 'Новая марина Хургады, ворота 1, за 15 минут до отправления.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000006', 'fr', 'Bateau à fond de verre : les récifs sans se mouiller', 'Deux heures à observer coraux et poissons à travers le fond vitré du bateau.', 'La façon la plus simple de voir les récifs de la mer Rouge : installez-vous sur le pont inférieur et observez coraux et poissons à travers de grandes vitres. Idéal pour les jeunes enfants, les grands-parents et tous ceux qui préfèrent rester au sec.', 'Départ de la marina
Croisière lente au-dessus de deux récifs
Court arrêt sans nourrir ni toucher quoi que ce soit : juste regarder
Retour à la marina', 'Sortie en bateau
Eau', 'Transfert depuis l’hôtel (option)', 'Convient à tous les âges.', 'Hurghada New Marina, porte 1, 15 minutes avant le départ.', false, true);
