insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000007', 'en', 'Sunset sailing cruise', 'Two and a half hours under sail as the sun goes down, with tea and snacks.', 'A small sailing boat leaves the marina in the late afternoon and sails along the coast while the sun sets behind the mountains. Quiet, slow and good for couples.', '16:00 boarding
16:15 sailing along the coast
Sunset on deck with tea and snacks
18:30 back at the marina', 'Sailing trip with skipper
Tea, soft drinks and snacks', 'Hotel transfer (optional add-on)', 'Bring a light jacket: it gets cooler on the water after sunset.', 'Hurghada Marina boulevard, pier C.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000007', 'ar', 'رحلة إبحار وقت الغروب', 'ساعتان ونصف بالشراع وقت غروب الشمس مع الشاي والوجبات الخفيفة.', 'مركب شراعي صغير يغادر المارينا آخر العصر ويبحر بمحاذاة الساحل بينما تغرب الشمس خلف الجبال. هادئ وبطيء ومناسب للأزواج.', '16:00 الصعود للمركب
16:15 الإبحار بمحاذاة الساحل
الغروب على السطح مع الشاي والوجبات الخفيفة
18:30 العودة إلى المارينا', 'رحلة الإبحار مع القبطان
شاي ومشروبات غازية ووجبات خفيفة', 'التوصيل من الفندق (إضافة اختيارية)', 'أحضر جاكيت خفيف: الجو يبرد على الماء بعد الغروب.', 'ممشى مارينا الغردقة، رصيف C.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000007', 'de', 'Segeltörn bei Sonnenuntergang', 'Zweieinhalb Stunden unter Segeln, während die Sonne untergeht, mit Tee und Snacks.', 'Ein kleines Segelboot verlässt am späten Nachmittag die Marina und segelt die Küste entlang, während die Sonne hinter den Bergen untergeht. Ruhig, gemächlich und schön für Paare.', '16:00 Einschiffen
16:15 Segeln entlang der Küste
Sonnenuntergang an Deck mit Tee und Snacks
18:30 Zurück an der Marina', 'Segeltörn mit Skipper
Tee, Softdrinks und Snacks', 'Hoteltransfer (optional zubuchbar)', 'Bringen Sie eine leichte Jacke mit: Nach Sonnenuntergang wird es auf dem Wasser kühler.', 'Hurghada Marina Boulevard, Steg C.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000007', 'ru', 'Парусная прогулка на закате', 'Два с половиной часа под парусом, пока садится солнце, с чаем и закусками.', 'Небольшая парусная лодка выходит из марины ближе к вечеру и идёт вдоль побережья, пока солнце садится за горы. Тихо, неспешно и отлично подходит для пар.', '16:00 посадка
16:15 прогулка под парусом вдоль побережья
Закат на палубе с чаем и закусками
18:30 возвращение в марину', 'Парусная прогулка со шкипером
Чай, безалкогольные напитки и закуски', 'Трансфер из отеля (дополнительная опция)', 'Возьмите лёгкую куртку: после заката на воде становится прохладнее.', 'Бульвар марины Хургады, причал C.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000007', 'fr', 'Croisière à la voile au coucher du soleil', 'Deux heures et demie sous voiles pendant que le soleil se couche, avec thé et en-cas.', 'Un petit voilier quitte la marina en fin d’après-midi et longe la côte pendant que le soleil se couche derrière les montagnes. Calme, paisible et parfait pour les couples.', '16:00 embarquement
16:15 navigation le long de la côte
Coucher de soleil sur le pont avec thé et en-cas
18:30 retour à la marina', 'Sortie à la voile avec skipper
Thé, boissons sans alcool et en-cas', 'Transfert depuis l’hôtel (option)', 'Prévoyez une veste légère : il fait plus frais sur l’eau après le coucher du soleil.', 'Boulevard de la marina de Hurghada, ponton C.', false, true);
