insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000008', 'en', 'Desert stargazing and barbecue dinner', 'Sunset in the dunes, dinner at a Bedouin camp and the night sky through a telescope.', 'You drive out of town in the late afternoon to reach a quiet desert camp before sunset. After a barbecue dinner around the fire, the lights go off and a guide shows you the stars and planets through a telescope.', '17:00 pickup and drive to the camp
Sunset from a dune
Barbecue dinner and tea
Stargazing with a telescope
22:00 back at your hotel', 'Transport from the meeting point to the camp
Dinner, tea and water
Telescope session with a guide', 'Hotel transfer (optional add-on)', 'Bring a warm layer: desert nights are cold from November to March.', 'Meeting point: Safari office, El Nasr Road.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000008', 'ar', 'مشاهدة النجوم في الصحراء مع عشاء مشويات', 'الغروب بين الكثبان، وعشاء في معسكر بدوي، والسماء ليلًا من التلسكوب.', 'تخرج من المدينة آخر العصر لتصل إلى معسكر هادئ في الصحراء قبل الغروب. وبعد عشاء مشويات حول النار تُطفأ الأنوار ويعرض لك المرشد النجوم والكواكب من خلال التلسكوب.', '17:00 الاستلام والتحرك إلى المعسكر
الغروب من فوق الكثبان
عشاء مشويات وشاي
مشاهدة النجوم بالتلسكوب
22:00 العودة إلى الفندق', 'المواصلات من نقطة التجمع إلى المعسكر
العشاء والشاي والمياه
جلسة التلسكوب مع مرشد', 'التوصيل من الفندق (إضافة اختيارية)', 'أحضر ملابس دافئة: ليالي الصحراء باردة من نوفمبر إلى مارس.', 'نقطة التجمع: مكتب السفاري، شارع النصر.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000008', 'de', 'Sterne beobachten in der Wüste mit Grill-Abendessen', 'Sonnenuntergang in den Dünen, Abendessen in einem Beduinencamp und der Nachthimmel durchs Teleskop.', 'Am späten Nachmittag fahren Sie aus der Stadt hinaus und erreichen vor Sonnenuntergang ein ruhiges Wüstencamp. Nach einem Grill-Abendessen am Feuer gehen die Lichter aus, und ein Guide zeigt Ihnen Sterne und Planeten durch ein Teleskop.', '17:00 Abholung und Fahrt zum Camp
Sonnenuntergang von einer Düne
Grill-Abendessen und Tee
Sterne beobachten mit Teleskop
22:00 Zurück in Ihrem Hotel', 'Transport vom Treffpunkt zum Camp
Abendessen, Tee und Wasser
Teleskop-Session mit Guide', 'Hoteltransfer (optional zubuchbar)', 'Bringen Sie eine warme Schicht mit: Von November bis März sind die Wüstennächte kalt.', 'Treffpunkt: Safari-Büro, El Nasr Road.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000008', 'ru', 'Звёзды в пустыне и ужин-барбекю', 'Закат в дюнах, ужин в бедуинском лагере и ночное небо в телескоп.', 'Ближе к вечеру вы выезжаете из города, чтобы до заката добраться до тихого лагеря в пустыне. После ужина-барбекю у костра свет гасят, и гид показывает вам звёзды и планеты в телескоп.', '17:00 выезд и дорога в лагерь
Закат на дюне
Ужин-барбекю и чай
Наблюдение за звёздами в телескоп
22:00 возвращение в отель', 'Трансфер от места встречи до лагеря
Ужин, чай и вода
Наблюдение в телескоп с гидом', 'Трансфер из отеля (дополнительная опция)', 'Возьмите тёплую одежду: с ноября по март ночи в пустыне холодные.', 'Место встречи: офис сафари, улица Эль-Наср.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000008', 'fr', 'Observation des étoiles et dîner barbecue dans le désert', 'Coucher de soleil dans les dunes, dîner dans un camp bédouin et ciel nocturne au télescope.', 'Vous quittez la ville en fin d’après-midi pour rejoindre un camp paisible dans le désert avant le coucher du soleil. Après un dîner barbecue autour du feu, les lumières s’éteignent et un guide vous montre les étoiles et les planètes au télescope.', '17:00 prise en charge et route vers le camp
Coucher de soleil depuis une dune
Dîner barbecue et thé
Observation des étoiles au télescope
22:00 retour à votre hôtel', 'Transport du point de rendez-vous au camp
Dîner, thé et eau
Observation au télescope avec un guide', 'Transfert depuis l’hôtel (option)', 'Prévoyez une couche chaude : les nuits dans le désert sont froides de novembre à mars.', 'Point de rendez-vous : bureau Safari, El Nasr Road.', false, true);
