insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000009', 'en', 'Sunrise camel ride', 'A slow camel ride into the mountains at dawn, then breakfast at camp.', 'An early start, rewarded with the desert at its quietest. You ride a camel led by a Bedouin guide to a viewpoint for sunrise, then share a simple breakfast at the camp.', '05:30 pickup
06:00 camel ride to the viewpoint
Sunrise
07:30 breakfast at camp
08:30 back to town', 'Camel ride with guide
Breakfast and tea', 'Hotel transfer (optional add-on)', 'Minimum age 6. Long trousers recommended.', 'Desert camp, Hurghada–Safaga road.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000009', 'ar', 'ركوب الجمل وقت الشروق', 'جولة هادئة على الجمل نحو الجبال مع الفجر، ثم فطار في المعسكر.', 'تبدأ مبكرًا لترى الصحراء في أهدأ أوقاتها. تركب جملًا يقوده مرشد بدوي إلى نقطة مطلة لمشاهدة الشروق، ثم تتناول فطارًا بسيطًا في المعسكر.', '05:30 الاستلام
06:00 جولة الجمل إلى النقطة المطلة
الشروق
07:30 الفطار في المعسكر
08:30 العودة إلى المدينة', 'ركوب الجمل مع مرشد
فطار وشاي', 'التوصيل من الفندق (إضافة اختيارية)', 'الحد الأدنى للسن 6 سنوات. يُفضل بنطلون طويل.', 'معسكر الصحراء، طريق الغردقة–سفاجا.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000009', 'de', 'Kamelritt bei Sonnenaufgang', 'Ein gemächlicher Kamelritt in die Berge im Morgengrauen, danach Frühstück im Camp.', 'Ein früher Start, belohnt mit der Wüste in ihrer stillsten Stunde. Sie reiten auf einem Kamel, geführt von einem Beduinen, zu einem Aussichtspunkt für den Sonnenaufgang und teilen danach ein einfaches Frühstück im Camp.', '05:30 Abholung
06:00 Kamelritt zum Aussichtspunkt
Sonnenaufgang
07:30 Frühstück im Camp
08:30 Zurück in die Stadt', 'Kamelritt mit Guide
Frühstück und Tee', 'Hoteltransfer (optional zubuchbar)', 'Mindestalter 6 Jahre. Lange Hosen empfohlen.', 'Wüstencamp, Straße Hurghada–Safaga.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000009', 'ru', 'Прогулка на верблюде на рассвете', 'Неспешная прогулка на верблюде в горы на рассвете, а затем завтрак в лагере.', 'Ранний подъём, за который вас вознаградит пустыня в самый тихий час. Бедуин-проводник ведёт вашего верблюда к смотровой площадке, где вы встретите рассвет, а затем вас ждёт простой завтрак в лагере.', '05:30 выезд
06:00 прогулка на верблюде к смотровой площадке
Рассвет
07:30 завтрак в лагере
08:30 возвращение в город', 'Прогулка на верблюде с гидом
Завтрак и чай', 'Трансфер из отеля (дополнительная опция)', 'Минимальный возраст — 6 лет. Рекомендуются длинные брюки.', 'Лагерь в пустыне, трасса Хургада — Сафага.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000009', 'fr', 'Balade à dos de chameau au lever du soleil', 'Une balade tranquille à dos de chameau vers les montagnes à l’aube, puis petit-déjeuner au camp.', 'Un départ matinal, récompensé par le désert à son moment le plus paisible. Vous montez un chameau mené par un guide bédouin jusqu’à un point de vue pour le lever du soleil, puis partagez un petit-déjeuner simple au camp.', '05:30 prise en charge
06:00 balade à dos de chameau jusqu’au point de vue
Lever du soleil
07:30 petit-déjeuner au camp
08:30 retour en ville', 'Balade à dos de chameau avec guide
Petit-déjeuner et thé', 'Transfert depuis l’hôtel (option)', 'Âge minimum : 6 ans. Pantalon long recommandé.', 'Camp dans le désert, route Hurghada–Safaga.', false, true);
