insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000010', 'en', 'Super safari: jeep, quad, camel and dinner', 'Half a day in the desert: jeep ride, quad, camel, a Bedouin village and dinner.', 'Everything in one afternoon. A jeep takes you deep into the desert, you ride a quad and a camel, visit a Bedouin village and end with dinner and a show under the stars.', '13:00 jeep ride into the desert
Quad ride (30 minutes)
Camel ride and Bedouin village
Sunset and dinner
19:00 back in town', 'Jeep, quad and camel rides
Guide
Dinner and drinks', 'Hotel transfer (optional add-on)', 'Children ride as passengers with an adult on the quad.', 'Safari office, El Nasr Road.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000010', 'ar', 'سوبر سفاري: جيب وموتوسيكل وجمل وعشاء', 'نصف يوم في الصحراء: جيب وموتوسيكل رباعي وجمل وقرية بدوية وعشاء.', 'كل شيء في عصرية واحدة. ينقلك الجيب إلى عمق الصحراء، وتركب الموتوسيكل الرباعي والجمل، وتزور قرية بدوية، ثم تختم بعشاء وعرض تحت النجوم.', '13:00 جولة الجيب في الصحراء
قيادة الموتوسيكل الرباعي (30 دقيقة)
ركوب الجمل والقرية البدوية
الغروب والعشاء
19:00 العودة إلى المدينة', 'جولات الجيب والموتوسيكل والجمل
مرشد
عشاء ومشروبات', 'التوصيل من الفندق (إضافة اختيارية)', 'الأطفال يركبون كركاب مع شخص بالغ على الموتوسيكل.', 'مكتب السفاري، شارع النصر.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000010', 'de', 'Super-Safari: Jeep, Quad, Kamel und Abendessen', 'Ein halber Tag in der Wüste: Jeepfahrt, Quad, Kamel, ein Beduinendorf und Abendessen.', 'Alles an einem Nachmittag. Ein Jeep bringt Sie tief in die Wüste, Sie fahren Quad und reiten auf einem Kamel, besuchen ein Beduinendorf und lassen den Tag mit Abendessen und einer Show unter den Sternen ausklingen.', '13:00 Jeepfahrt in die Wüste
Quadfahrt (30 Minuten)
Kamelritt und Beduinendorf
Sonnenuntergang und Abendessen
19:00 Zurück in der Stadt', 'Jeep-, Quad- und Kamelritt
Guide
Abendessen und Getränke', 'Hoteltransfer (optional zubuchbar)', 'Kinder fahren auf dem Quad als Beifahrer mit einem Erwachsenen mit.', 'Safari-Büro, El Nasr Road.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000010', 'ru', 'Супер-сафари: джип, квадроцикл, верблюд и ужин', 'Полдня в пустыне: поездка на джипе, квадроцикл, верблюд, бедуинская деревня и ужин.', 'Всё за один день. Джип увезёт вас вглубь пустыни, вы прокатитесь на квадроцикле и верблюде, побываете в бедуинской деревне, а завершите день ужином и шоу под звёздами.', '13:00 поездка на джипе в пустыню
Квадроцикл (30 минут)
Прогулка на верблюде и бедуинская деревня
Закат и ужин
19:00 возвращение в город', 'Поездки на джипе, квадроцикле и верблюде
Гид
Ужин и напитки', 'Трансфер из отеля (дополнительная опция)', 'Дети едут на квадроцикле пассажирами вместе со взрослым.', 'Офис сафари, улица Эль-Наср.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000010', 'fr', 'Super safari : jeep, quad, chameau et dîner', 'Une demi-journée dans le désert : jeep, quad, chameau, un village bédouin et le dîner.', 'Tout en un après-midi. Une jeep vous emmène au cœur du désert, vous faites du quad et du chameau, visitez un village bédouin et terminez par un dîner et un spectacle sous les étoiles.', '13:00 jeep vers le désert
Quad (30 minutes)
Balade à dos de chameau et village bédouin
Coucher de soleil et dîner
19:00 retour en ville', 'Balades en jeep, en quad et à dos de chameau
Guide
Dîner et boissons', 'Transfert depuis l’hôtel (option)', 'Les enfants montent en passagers avec un adulte sur le quad.', 'Bureau Safari, El Nasr Road.', false, true);
