insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000011', 'en', 'El Dahar old town and market walk', 'Walk the old quarter with a local guide: the mosque, the fish market and a spice shop.', 'A walking tour of El Dahar, the oldest part of Hurghada. Your guide explains how the fishing town grew into a resort city, takes you through the market lanes and stops at a family spice shop for tea.', 'Meet at El Mina Mosque square
Old quarter lanes
Fish market and fruit market
Tea at a spice shop
End near the Hurghada Marina', 'Local guide
Tea at the spice shop', 'Hotel transfer (optional add-on)
Purchases', 'Shoulders and knees covered for the mosque visit.', 'El Mina Mosque square, by the main gate.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000011', 'ar', 'جولة الدهار القديمة والسوق', 'تمشية في الحي القديم مع مرشد محلي: المسجد وسوق السمك ومحل عطارة.', 'جولة على الأقدام في الدهار، أقدم أحياء الغردقة. يشرح لك المرشد كيف تحولت قرية الصيادين إلى مدينة سياحية، ويمر بك على حواري السوق ويتوقف عند محل عطارة عائلي لشرب الشاي.', 'اللقاء في ساحة مسجد الميناء
حواري الحي القديم
سوق السمك وسوق الفاكهة
شاي في محل العطارة
النهاية بالقرب من مارينا الغردقة', 'مرشد محلي
شاي في محل العطارة', 'التوصيل من الفندق (إضافة اختيارية)
المشتريات', 'تغطية الكتفين والركبتين لزيارة المسجد.', 'ساحة مسجد الميناء، عند البوابة الرئيسية.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000011', 'de', 'Rundgang durch die Altstadt El Dahar und den Markt', 'Erkunden Sie das alte Viertel mit einem einheimischen Guide: die Moschee, den Fischmarkt und einen Gewürzladen.', 'Ein Rundgang durch El Dahar, den ältesten Teil von Hurghada. Ihr Guide erzählt, wie aus dem Fischerort eine Urlaubsstadt wurde, führt Sie durch die Marktgassen und hält für einen Tee in einem familiengeführten Gewürzladen.', 'Treffen am Platz der El-Mina-Moschee
Gassen des alten Viertels
Fischmarkt und Obstmarkt
Tee in einem Gewürzladen
Ende nahe der Hurghada Marina', 'Einheimischer Guide
Tee im Gewürzladen', 'Hoteltransfer (optional zubuchbar)
Einkäufe', 'Schultern und Knie müssen für den Moscheebesuch bedeckt sein.', 'Platz der El-Mina-Moschee, am Haupttor.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000011', 'ru', 'Прогулка по старому городу Эль-Дахар и рынку', 'Прогуляйтесь по старому кварталу с местным гидом: мечеть, рыбный рынок и лавка специй.', 'Пешая экскурсия по Эль-Дахару, самой старой части Хургады. Гид расскажет, как рыбацкий посёлок превратился в курортный город, проведёт вас по рыночным улочкам и сделает остановку на чай в семейной лавке специй.', 'Встреча на площади у мечети Эль-Мина
Улочки старого квартала
Рыбный и фруктовый рынки
Чай в лавке специй
Окончание рядом с мариной Хургады', 'Местный гид
Чай в лавке специй', 'Трансфер из отеля (дополнительная опция)
Покупки', 'Для посещения мечети плечи и колени должны быть закрыты.', 'Площадь у мечети Эль-Мина, у главных ворот.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000011', 'fr', 'Balade dans la vieille ville et le marché d’El Dahar', 'Parcourez le vieux quartier avec un guide local : la mosquée, le marché aux poissons et une boutique d’épices.', 'Une visite à pied d’El Dahar, le plus ancien quartier de Hurghada. Votre guide vous explique comment le village de pêcheurs est devenu une ville balnéaire, vous emmène dans les ruelles du marché et fait une halte dans une boutique d’épices familiale pour un thé.', 'Rendez-vous place de la mosquée El Mina
Ruelles du vieux quartier
Marché aux poissons et marché aux fruits
Thé dans une boutique d’épices
Fin près de la marina de Hurghada', 'Guide local
Thé à la boutique d’épices', 'Transfert depuis l’hôtel (option)
Achats', 'Épaules et genoux couverts pour la visite de la mosquée.', 'Place de la mosquée El Mina, près de l’entrée principale.', false, true);
