insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000012', 'en', 'Luxor day trip: temples and the West Bank', 'A long day by road to Luxor with an Egyptologist guide: Karnak, the Valley of the Kings and lunch by the Nile.', 'A full day: about four hours each way by air-conditioned minibus. In Luxor an Egyptologist guide takes you to Karnak Temple, across the Nile to the Valley of the Kings, and to lunch with a view of the river.
Entrance fees are included for the sites in the itinerary; special tombs cost extra on site.', '05:00 pickup from your hotel
09:00 Karnak Temple
11:30 Valley of the Kings
13:30 lunch by the Nile
15:00 Hatshepsut Temple (outside view)
16:00 drive back
20:00 back at your hotel', 'Transport with air conditioning
Egyptologist guide
Entrance fees for listed sites
Lunch and water', 'Special tombs and photo permits
Tips', 'Passport copy required. Long day: not ideal for children under 6.', 'Pickup from your hotel lobby (Hurghada area included).', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000012', 'ar', 'رحلة يوم إلى الأقصر: المعابد والبر الغربي', 'يوم طويل بالطريق إلى الأقصر مع مرشد أثري: الكرنك ووادي الملوك وغداء على النيل.', 'يوم كامل: حوالي أربع ساعات في كل اتجاه بميني باص مكيف. في الأقصر يرافقك مرشد أثري إلى معبد الكرنك، ثم تعبر النيل إلى وادي الملوك، وتتناول الغداء بإطلالة على النهر.
رسوم الدخول مشمولة للمواقع المذكورة في البرنامج؛ المقابر الخاصة تُدفع في الموقع.', '05:00 الاستلام من الفندق
09:00 معبد الكرنك
11:30 وادي الملوك
13:30 الغداء على النيل
15:00 معبد حتشبسوت (من الخارج)
16:00 طريق العودة
20:00 الوصول إلى الفندق', 'مواصلات مكيفة
مرشد أثري
رسوم دخول المواقع المذكورة
غداء ومياه', 'المقابر الخاصة وتصاريح التصوير
الإكراميات', 'صورة جواز السفر مطلوبة. يوم طويل: غير مثالي للأطفال أقل من 6 سنوات.', 'الاستلام من استقبال الفندق (منطقة الغردقة مشمولة).', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000012', 'de', 'Tagesausflug nach Luxor: Tempel und Westbank', 'Ein langer Tag auf der Straße nach Luxor mit einem Ägyptologen: Karnak, das Tal der Könige und Mittagessen am Nil.', 'Ein ganzer Tag: etwa vier Stunden pro Strecke im klimatisierten Minibus. In Luxor führt Sie ein Ägyptologe zum Karnak-Tempel, über den Nil ins Tal der Könige und zum Mittagessen mit Blick auf den Fluss.
Die Eintrittsgelder für die Stätten im Programm sind inklusive; besondere Gräber kosten vor Ort extra.', '05:00 Abholung vom Hotel
09:00 Karnak-Tempel
11:30 Tal der Könige
13:30 Mittagessen am Nil
15:00 Hatschepsut-Tempel (Außenansicht)
16:00 Rückfahrt
20:00 Zurück in Ihrem Hotel', 'Klimatisierter Transport
Ägyptologe als Guide
Eintrittsgelder für die genannten Stätten
Mittagessen und Wasser', 'Besondere Gräber und Fotogenehmigungen
Trinkgelder', 'Kopie des Reisepasses erforderlich. Langer Tag: für Kinder unter 6 Jahren nicht ideal.', 'Abholung in Ihrer Hotellobby (Raum Hurghada inklusive).', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000012', 'ru', 'Поездка в Луксор: храмы и Западный берег', 'Долгий день в дороге до Луксора с гидом-египтологом: Карнак, Долина царей и обед на берегу Нила.', 'Целый день: около четырёх часов в одну сторону на микроавтобусе с кондиционером. В Луксоре гид-египтолог проведёт вас по Карнакскому храму, переправит через Нил в Долину царей и на обед с видом на реку.
Входные билеты на объекты из программы включены; особые гробницы оплачиваются дополнительно на месте.', '05:00 выезд из отеля
09:00 Карнакский храм
11:30 Долина царей
13:30 обед на берегу Нила
15:00 храм Хатшепсут (осмотр снаружи)
16:00 обратная дорога
20:00 возвращение в отель', 'Транспорт с кондиционером
Гид-египтолог
Входные билеты на указанные объекты
Обед и вода', 'Особые гробницы и разрешения на фотосъёмку
Чаевые', 'Нужна копия паспорта. Долгий день: не лучший вариант для детей до 6 лет.', 'Трансфер из лобби вашего отеля (включая районы Хургады).', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000012', 'fr', 'Journée à Louxor : temples et rive ouest', 'Une longue journée sur la route de Louxor avec un guide égyptologue : Karnak, la Vallée des Rois et déjeuner au bord du Nil.', 'Une journée complète : environ quatre heures de trajet dans chaque sens en minibus climatisé. À Louxor, un guide égyptologue vous emmène au temple de Karnak, de l’autre côté du Nil à la Vallée des Rois, puis déjeuner avec vue sur le fleuve.
Les droits d’entrée sont inclus pour les sites du programme ; les tombes spéciales sont payantes sur place.', '05:00 prise en charge à votre hôtel
09:00 temple de Karnak
11:30 Vallée des Rois
13:30 déjeuner au bord du Nil
15:00 temple d’Hatchepsout (vue extérieure)
16:00 trajet retour
20:00 retour à votre hôtel', 'Transport climatisé
Guide égyptologue
Droits d’entrée des sites mentionnés
Déjeuner et eau', 'Tombes spéciales et permis photo
Pourboires', 'Copie du passeport obligatoire. Longue journée : peu adaptée aux enfants de moins de 6 ans.', 'Prise en charge dans le hall de votre hôtel (secteur de Hurghada inclus).', false, true);
