insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000013', 'en', 'Red Sea fishing morning', 'Bottom fishing from a small boat with rods, bait and a grilled-fish lunch.', 'Head out with a local captain to the fishing grounds north of Hurghada. Rods, lines and bait are ready on board and the crew shows beginners how to drop and reel in.
What you catch is cleaned and grilled on board for lunch.', '07:30 boat leaves the marina
08:30 first fishing spot
10:30 second spot
12:00 grilled catch for lunch
12:30 back to the marina', 'Boat, captain and crew
Rods, lines and bait
Lunch with your catch
Water and tea', 'Hotel transfer (optional add-on)
Tips', 'Calm-sea trip; still bring motion-sickness tablets if you need them.', 'Hurghada New Marina, gate 2, 20 minutes before departure.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000013', 'ar', 'صباح صيد في البحر الأحمر', 'صيد قاعي من مركب صغير مع السنارات والطُعم وغداء سمك مشوي.', 'اخرج مع ريّس محلي إلى أماكن الصيد شمال الغردقة. السنارات والخيوط والطُعم جاهزة على المركب، ويعلّم الطاقم المبتدئين طريقة الصيد.
ما تصطاده يُنظّف ويُشوى على المركب للغداء.', '07:30 تحرك المركب من المارينا
08:30 مكان الصيد الأول
10:30 المكان الثاني
12:00 غداء من صيدك
12:30 العودة للمارينا', 'المركب والريّس والطاقم
السنارات والخيوط والطُعم
غداء من صيدك
مياه وشاي', 'التوصيل من الفندق (إضافة اختيارية)
الإكراميات', 'رحلة في بحر هادئ؛ أحضر أقراص دوار البحر إن احتجت.', 'مارينا الغردقة الجديدة، البوابة 2، قبل الموعد بـ 20 دقيقة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000013', 'de', 'Angelmorgen im Roten Meer', 'Grundangeln von einem kleinen Boot aus, mit Ruten, Köder und einem Mittagessen mit gegrilltem Fisch.', 'Fahren Sie mit einem einheimischen Kapitän zu den Fanggründen nördlich von Hurghada. Ruten, Schnüre und Köder liegen an Bord bereit, und die Crew zeigt Anfängern, wie man die Leine auswirft und einholt.
Ihr Fang wird an Bord ausgenommen und zum Mittagessen gegrillt.', '07:30 Das Boot verlässt die Marina
08:30 Erster Angelplatz
10:30 Zweiter Angelplatz
12:00 Gegrillter Fang zum Mittagessen
12:30 Zurück zur Marina', 'Boot, Kapitän und Crew
Ruten, Schnüre und Köder
Mittagessen mit Ihrem Fang
Wasser und Tee', 'Hoteltransfer (optional zubuchbar)
Trinkgelder', 'Ausflug bei ruhiger See; bringen Sie bei Bedarf trotzdem Tabletten gegen Reiseübelkeit mit.', 'Hurghada New Marina, Tor 2, 20 Minuten vor Abfahrt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000013', 'ru', 'Утренняя рыбалка в Красном море', 'Донная рыбалка с небольшой лодки: удочки, наживка и обед из рыбы на гриле.', 'Отправляйтесь с местным капитаном к рыбным местам к северу от Хургады. Удочки, лески и наживка уже ждут на борту, а команда покажет новичкам, как забрасывать и вытаскивать снасть.
Ваш улов почистят и приготовят на гриле прямо на борту к обеду.', '07:30 отправление лодки из марины
08:30 первое место для рыбалки
10:30 второе место
12:00 обед из улова на гриле
12:30 возвращение в марину', 'Лодка, капитан и команда
Удочки, лески и наживка
Обед из вашего улова
Вода и чай', 'Трансфер из отеля (дополнительная опция)
Чаевые', 'Прогулка проходит при спокойном море, но если нужно, всё же возьмите таблетки от укачивания.', 'Новая марина Хургады, ворота 2, за 20 минут до отправления.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000013', 'fr', 'Matinée de pêche en mer Rouge', 'Pêche au fond depuis un petit bateau, avec cannes, appâts et déjeuner de poisson grillé.', 'Partez avec un capitaine local vers les zones de pêche au nord de Hurghada. Cannes, lignes et appâts vous attendent à bord, et l’équipage montre aux débutants comment descendre la ligne et remonter le poisson.
Votre pêche est nettoyée et grillée à bord pour le déjeuner.', '07:30 départ du bateau depuis la marina
08:30 premier coin de pêche
10:30 deuxième coin
12:00 votre pêche grillée au déjeuner
12:30 retour à la marina', 'Bateau, capitaine et équipage
Cannes, lignes et appâts
Déjeuner avec votre pêche
Eau et thé', 'Transfert depuis l’hôtel (option)
Pourboires', 'Sortie par mer calme ; prenez tout de même des comprimés contre le mal de mer si besoin.', 'Hurghada New Marina, porte 2, 20 minutes avant le départ.', false, true);
