insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000014', 'en', 'Two-tank reef dive for certified divers', 'Two guided dives on Hurghada''s best reefs, with full equipment and lunch on board.', 'For divers who already hold a certificate. The dive guide picks two reefs that suit the day''s conditions and your level, with a surface interval and lunch between the dives.
Bring your certification card and logbook.', '08:00 check-in at the dive centre
09:00 boat leaves
10:00 first dive (about 50 minutes)
11:00 surface interval and lunch
12:30 second dive
14:00 back at the marina', 'Two guided dives
Tank, weights and full equipment
Lunch, water and tea', 'Hotel transfer (optional add-on)
Nitrox (ask the centre)
Marine park fee', 'Open Water certificate or equivalent required.
No flying within 24 hours after diving.', 'Dive centre, Sheraton Road. Pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000014', 'ar', 'غطستان على الشعاب للغواصين المعتمدين', 'غطستان مع مرشد على أجمل شعاب الغردقة، بالمعدات الكاملة وغداء على المركب.', 'للغواصين الحاصلين على شهادة. يختار المرشد شعبتين تناسبان ظروف اليوم ومستواك، مع استراحة وغداء بين الغطستين.
أحضر بطاقة الشهادة ودفتر الغوص.', '08:00 التسجيل في مركز الغوص
09:00 تحرك المركب
10:00 الغطسة الأولى (حوالي 50 دقيقة)
11:00 استراحة وغداء
12:30 الغطسة الثانية
14:00 العودة للمارينا', 'غطستان مع مرشد
أسطوانة وأوزان ومعدات كاملة
غداء ومياه وشاي', 'التوصيل من الفندق (إضافة اختيارية)
النيتروكس (اسأل المركز)
رسوم المحمية', 'مطلوب شهادة Open Water أو ما يعادلها.
ممنوع الطيران خلال 24 ساعة بعد الغوص.', 'مركز الغوص، طريق الشيراتون. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000014', 'de', 'Zwei Rifftauchgänge für zertifizierte Taucher', 'Zwei geführte Tauchgänge an den schönsten Riffen Hurghadas, mit kompletter Ausrüstung und Mittagessen an Bord.', 'Für Taucher, die bereits ein Brevet haben. Der Tauchguide wählt zwei Riffe, die zu den Bedingungen des Tages und Ihrem Niveau passen, mit Oberflächenpause und Mittagessen zwischen den Tauchgängen.
Bringen Sie Ihre Brevetkarte und Ihr Logbuch mit.', '08:00 Check-in im Tauchzentrum
09:00 Abfahrt des Bootes
10:00 Erster Tauchgang (etwa 50 Minuten)
11:00 Oberflächenpause und Mittagessen
12:30 Zweiter Tauchgang
14:00 Zurück an der Marina', 'Zwei geführte Tauchgänge
Flasche, Blei und komplette Ausrüstung
Mittagessen, Wasser und Tee', 'Hoteltransfer (optional zubuchbar)
Nitrox (bitte im Tauchzentrum erfragen)
Meeresparkgebühr', 'Open-Water-Brevet oder gleichwertige Qualifikation erforderlich.
Kein Fliegen innerhalb von 24 Stunden nach dem Tauchen.', 'Tauchzentrum, Sheraton Road. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000014', 'ru', 'Два погружения на рифах для сертифицированных дайверов', 'Два погружения с гидом на лучших рифах Хургады, с полным снаряжением и обедом на борту.', 'Для дайверов, у которых уже есть сертификат. Гид выбирает два рифа с учётом условий дня и вашего уровня, а между погружениями — поверхностный интервал и обед.
Возьмите с собой сертификат и логбук.', '08:00 регистрация в дайвинг-центре
09:00 отправление лодки
10:00 первое погружение (около 50 минут)
11:00 поверхностный интервал и обед
12:30 второе погружение
14:00 возвращение в марину', 'Два погружения с гидом
Баллон, грузы и полное снаряжение
Обед, вода и чай', 'Трансфер из отеля (дополнительная опция)
Нитрокс (уточняйте в центре)
Сбор морского парка', 'Требуется сертификат Open Water или аналогичный.
Нельзя летать в течение 24 часов после погружения.', 'Дайвинг-центр, улица Шератон. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000014', 'fr', 'Deux plongées sur récif pour plongeurs certifiés', 'Deux plongées guidées sur les plus beaux récifs de Hurghada, avec équipement complet et déjeuner à bord.', 'Pour les plongeurs déjà certifiés. Le guide de plongée choisit deux récifs adaptés aux conditions du jour et à votre niveau, avec un intervalle de surface et le déjeuner entre les plongées.
Apportez votre carte de certification et votre carnet de plongée.', '08:00 accueil au centre de plongée
09:00 départ du bateau
10:00 première plongée (environ 50 minutes)
11:00 intervalle de surface et déjeuner
12:30 deuxième plongée
14:00 retour à la marina', 'Deux plongées guidées
Bouteille, plombs et équipement complet
Déjeuner, eau et thé', 'Transfert depuis l’hôtel (option)
Nitrox (renseignez-vous auprès du centre)
Taxe du parc marin', 'Niveau Open Water ou équivalent obligatoire.
Pas de vol en avion dans les 24 heures suivant la plongée.', 'Centre de plongée, Sheraton Road. Localisation sur votre bon.', false, true);
