insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000015', 'en', 'Wreck dive: a sunken ship near Hurghada', 'Dive a coral-covered wreck with an experienced guide; second dive on a reef.', 'A wreck dive for certified divers with some experience. After a detailed briefing you descend along the line and explore the outside of the ship, now home to corals and fish. Penetration is not part of this trip.
The centre checks your logbook before confirming, so this trip is booked on request.', '07:00 check-in and briefing
08:00 boat leaves
09:30 wreck dive
11:00 lunch on board
12:30 reef dive
14:30 back at the marina', 'Two guided dives (wreck and reef)
Full equipment
Lunch and drinks', 'Hotel transfer (optional add-on)
Marine park fee', 'Advanced certificate or 20 logged dives.
Minimum age 15.', 'Dive centre, Sheraton Road. Pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000015', 'ar', 'غطسة حطام: سفينة غارقة قرب الغردقة', 'غطسة على حطام سفينة تغطيه الشعاب مع مرشد خبير، وغطسة ثانية على الشعاب.', 'غطسة حطام للغواصين المعتمدين أصحاب الخبرة. بعد شرح مفصل تنزل على الحبل وتستكشف السفينة من الخارج، وقد أصبحت بيتًا للشعاب والأسماك. الدخول إلى السفينة ليس ضمن الرحلة.
يراجع المركز دفتر الغوص قبل التأكيد، لذلك الحجز بالطلب.', '07:00 التسجيل والشرح
08:00 تحرك المركب
09:30 غطسة الحطام
11:00 الغداء على المركب
12:30 غطسة الشعاب
14:30 العودة للمارينا', 'غطستان مع مرشد (حطام وشعاب)
معدات كاملة
غداء ومشروبات', 'التوصيل من الفندق (إضافة اختيارية)
رسوم المحمية', 'شهادة Advanced أو 20 غطسة مسجلة.
الحد الأدنى للسن 15 عامًا.', 'مركز الغوص، طريق الشيراتون. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000015', 'de', 'Wracktauchen: ein gesunkenes Schiff bei Hurghada', 'Betauchen Sie mit einem erfahrenen Guide ein mit Korallen bewachsenes Wrack; der zweite Tauchgang führt an ein Riff.', 'Ein Wracktauchgang für zertifizierte Taucher mit etwas Erfahrung. Nach einem ausführlichen Briefing steigen Sie an der Leine ab und erkunden das Schiff von außen, das heute Korallen und Fischen ein Zuhause bietet. Ein Eindringen ins Wrack ist nicht Teil dieses Ausflugs.
Das Tauchzentrum prüft vor der Bestätigung Ihr Logbuch, daher wird dieser Ausflug auf Anfrage gebucht.', '07:00 Check-in und Briefing
08:00 Abfahrt des Bootes
09:30 Wracktauchgang
11:00 Mittagessen an Bord
12:30 Rifftauchgang
14:30 Zurück an der Marina', 'Zwei geführte Tauchgänge (Wrack und Riff)
Komplette Ausrüstung
Mittagessen und Getränke', 'Hoteltransfer (optional zubuchbar)
Meeresparkgebühr', 'Advanced-Brevet oder 20 geloggte Tauchgänge.
Mindestalter 15 Jahre.', 'Tauchzentrum, Sheraton Road. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000015', 'ru', 'Дайвинг на затонувшем корабле у Хургады', 'Погружение на затонувший корабль, покрытый кораллами, с опытным гидом; второе погружение — на рифе.', 'Погружение на затонувший корабль для сертифицированных дайверов с некоторым опытом. После подробного брифинга вы спускаетесь по линю и осматриваете корабль снаружи — теперь это дом для кораллов и рыб. Проникновение внутрь в программу не входит.
Перед подтверждением центр проверяет ваш логбук, поэтому эта поездка бронируется по запросу.', '07:00 регистрация и брифинг
08:00 отправление лодки
09:30 погружение на затонувший корабль
11:00 обед на борту
12:30 погружение на рифе
14:30 возвращение в марину', 'Два погружения с гидом (затонувший корабль и риф)
Полное снаряжение
Обед и напитки', 'Трансфер из отеля (дополнительная опция)
Сбор морского парка', 'Сертификат Advanced или 20 записанных в логбук погружений.
Минимальный возраст — 15 лет.', 'Дайвинг-центр, улица Шератон. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000015', 'fr', 'Plongée sur épave : un navire coulé près de Hurghada', 'Plongez sur une épave couverte de coraux avec un guide expérimenté ; deuxième plongée sur un récif.', 'Une plongée sur épave pour plongeurs certifiés ayant un peu d’expérience. Après un briefing détaillé, vous descendez le long du bout et explorez l’extérieur du navire, aujourd’hui habité par les coraux et les poissons. La pénétration ne fait pas partie de cette sortie.
Le centre vérifie votre carnet de plongée avant de confirmer : cette sortie est donc réservée sur demande.', '07:00 accueil et briefing
08:00 départ du bateau
09:30 plongée sur l’épave
11:00 déjeuner à bord
12:30 plongée sur le récif
14:30 retour à la marina', 'Deux plongées guidées (épave et récif)
Équipement complet
Déjeuner et boissons', 'Transfert depuis l’hôtel (option)
Taxe du parc marin', 'Niveau Advanced ou 20 plongées enregistrées.
Âge minimum : 15 ans.', 'Centre de plongée, Sheraton Road. Localisation sur votre bon.', false, true);
