insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000016', 'en', 'Parasailing over the bay', 'About 10 minutes in the air above the sea, alone or in tandem, with the beach below.', 'Take off from the back of the boat and rise slowly above the bay. The flight is calm and quiet; you land back on the boat dry. Tandem flights are possible for two people up to the combined weight limit.', 'Short safety briefing on the beach
Boat ride to the flight area
About 10 minutes in the air
Back to the beach', 'Flight with harness and life vest
Boat ride', 'Hotel transfer (optional add-on)
Photos and videos', 'Minimum age 8 (children fly in tandem with an adult).
Cancelled in strong wind: you get another time or a full refund.', 'Water sports hut on the public beach, Sheraton Road.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000016', 'ar', 'باراشوت فوق الخليج', 'حوالي 10 دقائق في الهواء فوق البحر، بمفردك أو مع شخص آخر، والشاطئ تحتك.', 'تنطلق من مؤخرة المركب وترتفع ببطء فوق الخليج. الطيران هادئ وتهبط على المركب دون أن تبتل. الطيران الثنائي متاح لشخصين في حدود الوزن المسموح.', 'شرح قصير للسلامة على الشاطئ
المركب إلى منطقة الطيران
حوالي 10 دقائق في الهواء
العودة للشاطئ', 'الطيران مع الحزام وسترة النجاة
رحلة المركب', 'التوصيل من الفندق (إضافة اختيارية)
الصور والفيديو', 'الحد الأدنى للسن 8 سنوات (الأطفال مع شخص بالغ).
يُلغى عند اشتداد الرياح: موعد آخر أو استرداد كامل.', 'كشك الرياضات المائية على الشاطئ العام، طريق الشيراتون.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000016', 'de', 'Parasailing über der Bucht', 'Etwa 10 Minuten in der Luft über dem Meer, allein oder im Tandem, mit dem Strand unter Ihnen.', 'Sie starten vom Heck des Bootes und steigen langsam über die Bucht auf. Der Flug ist ruhig und leise; Sie landen trocken wieder auf dem Boot. Tandemflüge für zwei Personen sind bis zum gemeinsamen Gewichtslimit möglich.', 'Kurze Sicherheitseinweisung am Strand
Bootsfahrt zum Fluggebiet
Etwa 10 Minuten in der Luft
Zurück zum Strand', 'Flug mit Gurtzeug und Schwimmweste
Bootsfahrt', 'Hoteltransfer (optional zubuchbar)
Fotos und Videos', 'Mindestalter 8 Jahre (Kinder fliegen im Tandem mit einem Erwachsenen).
Bei starkem Wind abgesagt: Sie erhalten einen anderen Termin oder den vollen Betrag zurück.', 'Wassersporthütte am öffentlichen Strand, Sheraton Road.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000016', 'ru', 'Парасейлинг над бухтой', 'Около 10 минут в воздухе над морем, в одиночку или вдвоём, а под вами — пляж.', 'Взлетите с кормы катера и медленно поднимитесь над бухтой. Полёт спокойный и тихий, а приземляетесь вы обратно на катер сухими. Возможен полёт вдвоём, если общий вес не превышает лимит.', 'Короткий инструктаж по безопасности на пляже
Поездка на катере к месту полёта
Около 10 минут в воздухе
Возвращение на пляж', 'Полёт с подвесной системой и спасательным жилетом
Прогулка на катере', 'Трансфер из отеля (дополнительная опция)
Фото и видео', 'Минимальный возраст — 8 лет (дети летают в паре со взрослым).
При сильном ветре полёт отменяется: вам предложат другое время или полностью вернут деньги.', 'Пункт водных видов спорта на городском пляже, улица Шератон.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000016', 'fr', 'Parachute ascensionnel au-dessus de la baie', 'Environ 10 minutes dans les airs au-dessus de la mer, seul ou en tandem, avec la plage en contrebas.', 'Décollez depuis l’arrière du bateau et élevez-vous doucement au-dessus de la baie. Le vol est calme et silencieux ; vous atterrissez au sec sur le bateau. Les vols en tandem sont possibles à deux, dans la limite du poids total autorisé.', 'Court briefing sécurité sur la plage
Trajet en bateau jusqu’à la zone de vol
Environ 10 minutes dans les airs
Retour à la plage', 'Vol avec harnais et gilet de sauvetage
Sortie en bateau', 'Transfert depuis l’hôtel (option)
Photos et vidéos', 'Âge minimum : 8 ans (les enfants volent en tandem avec un adulte).
Annulé en cas de vent fort : vous obtenez un autre créneau ou un remboursement intégral.', 'Cabane des sports nautiques sur la plage publique, Sheraton Road.', false, true);
