insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000017', 'en', 'Kitesurfing taster lesson in El Gouna', 'Three hours with a certified instructor: kite control on land, then body-dragging in shallow water.', 'El Gouna''s flat, shallow lagoons are among the best places to learn. Your instructor starts with kite control on the beach, then takes you into knee-deep water to feel the pull of the kite. With good wind, some students stand on the board by the end.
Lessons depend on the wind, so the school confirms your time on request.', 'Meet the instructor and safety talk
Kite control on land
Water session in the shallow lagoon
Debrief and next steps', 'Certified instructor (1 for 2 students)
Kite, board, harness, helmet, wetsuit', 'Hotel transfer (optional add-on)', 'Must be able to swim.
Minimum age 12, minimum weight 40 kg.', 'Kite station, Mangroovy beach, El Gouna.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000017', 'ar', 'درس تجريبي في الكايت سيرف بالجونة', 'ثلاث ساعات مع مدرب معتمد: التحكم في الطائرة على الشاطئ، ثم التدريب في المياه الضحلة.', 'بحيرات الجونة الضحلة والهادئة من أفضل أماكن التعلم. يبدأ المدرب بالتحكم في الطائرة على الشاطئ، ثم ينزل بك إلى مياه حتى الركبة لتشعر بسحب الطائرة. ومع رياح جيدة يقف بعض المتدربين على اللوح في نهاية الدرس.
الدروس تعتمد على الرياح، لذلك تؤكد المدرسة الموعد بالطلب.', 'مقابلة المدرب وشرح السلامة
التحكم في الطائرة على الشاطئ
جلسة في المياه الضحلة
مراجعة والخطوات التالية', 'مدرب معتمد (مدرب لكل متدربين)
الطائرة واللوح والحزام والخوذة وبدلة السباحة', 'التوصيل من الفندق (إضافة اختيارية)', 'يجب إجادة السباحة.
الحد الأدنى للسن 12 عامًا والوزن 40 كجم.', 'محطة الكايت، شاطئ مانجروفي، الجونة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000017', 'de', 'Kitesurf-Schnupperstunde in El Gouna', 'Drei Stunden mit einem zertifizierten Instruktor: Kitekontrolle an Land, dann Bodydragging im flachen Wasser.', 'Die flachen, ruhigen Lagunen von El Gouna gehören zu den besten Orten zum Lernen. Ihr Instruktor beginnt mit der Kitekontrolle am Strand und nimmt Sie dann mit ins knietiefe Wasser, damit Sie den Zug des Kites spüren. Bei gutem Wind stehen manche Schüler am Ende schon auf dem Board.
Der Unterricht ist windabhängig, daher bestätigt die Schule Ihre Uhrzeit auf Anfrage.', 'Treffen mit dem Instruktor und Sicherheitseinweisung
Kitekontrolle an Land
Wassereinheit in der flachen Lagune
Nachbesprechung und nächste Schritte', 'Zertifizierter Instruktor (1 für 2 Schüler)
Kite, Board, Trapez, Helm, Neoprenanzug', 'Hoteltransfer (optional zubuchbar)', 'Sie müssen schwimmen können.
Mindestalter 12 Jahre, Mindestgewicht 40 kg.', 'Kitestation, Mangroovy Beach, El Gouna.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000017', 'ru', 'Пробный урок кайтсёрфинга в Эль-Гуне', 'Три часа с сертифицированным инструктором: управление кайтом на суше, затем боди-драг на мелководье.', 'Ровные мелкие лагуны Эль-Гуны — одно из лучших мест для обучения. Инструктор начинает с управления кайтом на пляже, а затем заводит вас в воду по колено, чтобы вы почувствовали тягу кайта. При хорошем ветре некоторые ученики к концу занятия уже встают на доску.
Занятия зависят от ветра, поэтому школа подтверждает время по запросу.', 'Встреча с инструктором и инструктаж по безопасности
Управление кайтом на суше
Занятие на воде в мелкой лагуне
Разбор занятия и дальнейшие шаги', 'Сертифицированный инструктор (1 на 2 учеников)
Кайт, доска, трапеция, шлем, гидрокостюм', 'Трансфер из отеля (дополнительная опция)', 'Необходимо уметь плавать.
Минимальный возраст — 12 лет, минимальный вес — 40 кг.', 'Кайт-станция, пляж Mangroovy, Эль-Гуна.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000017', 'fr', 'Cours d’initiation au kitesurf à El Gouna', 'Trois heures avec un moniteur certifié : maîtrise de l’aile à terre, puis body-drag en eau peu profonde.', 'Les lagunes plates et peu profondes d’El Gouna comptent parmi les meilleurs endroits pour apprendre. Votre moniteur commence par la maîtrise de l’aile sur la plage, puis vous emmène dans l’eau jusqu’aux genoux pour sentir la traction de l’aile. Avec un bon vent, certains élèves tiennent debout sur la planche en fin de cours.
Les cours dépendent du vent : l’école confirme donc votre horaire sur demande.', 'Rencontre avec le moniteur et consignes de sécurité
Maîtrise de l’aile à terre
Séance dans l’eau peu profonde de la lagune
Bilan et prochaines étapes', 'Moniteur certifié (1 pour 2 élèves)
Aile, planche, harnais, casque, combinaison', 'Transfert depuis l’hôtel (option)', 'Savoir nager.
Âge minimum : 12 ans, poids minimum : 40 kg.', 'Station de kite, plage Mangroovy, El Gouna.', false, true);
