insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000018', 'en', 'Water sports pack: jet ski, banana and tube', '15 minutes on a jet ski with an instructor, then a banana boat and a tube ride.', 'Three rides in one booking. You start with a 15-minute jet-ski ride (driving yourself, the instructor on board), then hold on tight on the banana boat and the tube pulled by a speedboat.', 'Safety briefing and life vests
15 minutes jet ski
Banana boat ride
Tube ride', 'Jet ski (15 min) with instructor
Banana boat and tube rides
Life vests', 'Hotel transfer (optional add-on)', 'Children 8–11 ride the banana and tube only, with an adult.
Not suitable during pregnancy.', 'Water sports hut on the public beach, Sheraton Road.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000018', 'ar', 'باقة الرياضات المائية: جت سكي وبنانا وتيوب', '15 دقيقة جت سكي مع مدرب، ثم البنانا بوت والتيوب.', 'ثلاث جولات في حجز واحد. تبدأ بـ 15 دقيقة على الجت سكي (تقود بنفسك والمدرب معك)، ثم تتمسك جيدًا على البنانا بوت والتيوب خلف المركب السريع.', 'شرح السلامة وسترات النجاة
15 دقيقة جت سكي
جولة البنانا بوت
جولة التيوب', 'جت سكي (15 دقيقة) مع مدرب
جولات البنانا والتيوب
سترات النجاة', 'التوصيل من الفندق (إضافة اختيارية)', 'الأطفال من 8 إلى 11 سنة: البنانا والتيوب فقط مع شخص بالغ.
غير مناسبة أثناء الحمل.', 'كشك الرياضات المائية على الشاطئ العام، طريق الشيراتون.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000018', 'de', 'Wassersport-Paket: Jetski, Banane und Tube', '15 Minuten auf dem Jetski mit Instruktor, danach eine Fahrt auf der Banane und dem Tube.', 'Drei Fahrten mit einer Buchung. Zuerst geht es 15 Minuten auf den Jetski (Sie fahren selbst, der Instruktor ist mit an Bord), dann heißt es auf der Banane und dem Tube gut festhalten, gezogen von einem Schnellboot.', 'Sicherheitseinweisung und Schwimmwesten
15 Minuten Jetski
Fahrt auf der Banane
Fahrt auf dem Tube', 'Jetski (15 Min.) mit Instruktor
Fahrten auf Banane und Tube
Schwimmwesten', 'Hoteltransfer (optional zubuchbar)', 'Kinder von 8–11 Jahren fahren nur Banane und Tube, mit einem Erwachsenen.
Nicht geeignet während der Schwangerschaft.', 'Wassersporthütte am öffentlichen Strand, Sheraton Road.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000018', 'ru', 'Пакет водных развлечений: гидроцикл, банан и плюшка', '15 минут на гидроцикле с инструктором, а затем катание на банане и на плюшке.', 'Три развлечения в одном бронировании. Сначала 15 минут на гидроцикле (вы за рулём, инструктор на борту), а затем держитесь крепче на банане и плюшке, которые тянет скоростной катер.', 'Инструктаж по безопасности и спасательные жилеты
15 минут на гидроцикле
Катание на банане
Катание на плюшке', 'Гидроцикл (15 мин) с инструктором
Катание на банане и плюшке
Спасательные жилеты', 'Трансфер из отеля (дополнительная опция)', 'Дети 8–11 лет катаются только на банане и плюшке, вместе со взрослым.
Не подходит при беременности.', 'Пункт водных видов спорта на городском пляже, улица Шератон.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000018', 'fr', 'Pack sports nautiques : jet-ski, bouée banane et bouée tractée', '15 minutes de jet-ski avec un moniteur, puis un tour de bouée banane et de bouée tractée.', 'Trois activités en une seule réservation. Vous commencez par 15 minutes de jet-ski (vous pilotez, le moniteur à bord), puis vous vous accrochez bien sur la bouée banane et la bouée tractée par un bateau rapide.', 'Briefing sécurité et gilets de sauvetage
15 minutes de jet-ski
Tour de bouée banane
Tour de bouée tractée', 'Jet-ski (15 min) avec moniteur
Tours de bouée banane et de bouée tractée
Gilets de sauvetage', 'Transfert depuis l’hôtel (option)', 'Les enfants de 8 à 11 ans font uniquement la bouée banane et la bouée tractée, avec un adulte.
Déconseillé pendant la grossesse.', 'Cabane des sports nautiques sur la plage publique, Sheraton Road.', false, true);
