insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000019', 'en', 'Stand-up paddle at sunrise or sunset', 'A guided paddle along the coast in the calm hours, with a short swim stop.', 'The sea is flattest early in the morning and before sunset. After a few minutes of practice on the sand, your guide leads a slow paddle along the coast, with a stop to swim and look at the shallow reef.', 'Board fitting and practice on the beach
Guided paddle along the coast
Swim stop
Back to the beach', 'Board, paddle and leash
Guide
Water', 'Hotel transfer (optional add-on)
Waterproof phone case', 'Must be able to swim. Minimum age 10.', 'Water sports hut on the public beach, Sheraton Road.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000019', 'ar', 'تجديف واقفًا عند الشروق أو الغروب', 'جولة تجديف مع مرشد على طول الساحل في أهدأ ساعات اليوم، مع توقف للسباحة.', 'البحر في أهدأ حالاته صباحًا وقبل الغروب. بعد دقائق من التدريب على الرمل يقودك المرشد في جولة هادئة على طول الساحل، مع توقف للسباحة ومشاهدة الشعاب الضحلة.', 'تجهيز اللوح والتدريب على الشاطئ
جولة تجديف مع مرشد
توقف للسباحة
العودة للشاطئ', 'اللوح والمجداف والحبل
مرشد
مياه', 'التوصيل من الفندق (إضافة اختيارية)
جراب هاتف مضاد للماء', 'يجب إجادة السباحة. الحد الأدنى للسن 10 سنوات.', 'كشك الرياضات المائية على الشاطئ العام، طريق الشيراتون.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000019', 'de', 'Stand-up-Paddling bei Sonnenaufgang oder Sonnenuntergang', 'Eine geführte Paddeltour entlang der Küste in den ruhigen Stunden, mit kurzem Badestopp.', 'Frühmorgens und vor Sonnenuntergang ist das Meer am ruhigsten. Nach ein paar Minuten Übung im Sand führt Ihr Guide Sie gemächlich paddelnd die Küste entlang, mit einem Stopp zum Schwimmen und zum Betrachten des flachen Riffs.', 'Board-Anpassung und Übung am Strand
Geführte Paddeltour entlang der Küste
Badestopp
Zurück zum Strand', 'Board, Paddel und Leash
Guide
Wasser', 'Hoteltransfer (optional zubuchbar)
Wasserdichte Handyhülle', 'Sie müssen schwimmen können. Mindestalter 10 Jahre.', 'Wassersporthütte am öffentlichen Strand, Sheraton Road.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000019', 'ru', 'Сапбординг на рассвете или на закате', 'Прогулка на сапах с гидом вдоль побережья в спокойные часы, с короткой остановкой для купания.', 'Рано утром и перед закатом море самое спокойное. После нескольких минут тренировки на песке гид ведёт вас в неспешную прогулку вдоль побережья с остановкой, чтобы искупаться и посмотреть на мелководный риф.', 'Подбор доски и тренировка на пляже
Прогулка с гидом вдоль побережья
Остановка для купания
Возвращение на пляж', 'Доска, весло и лиш
Гид
Вода', 'Трансфер из отеля (дополнительная опция)
Водонепроницаемый чехол для телефона', 'Необходимо уметь плавать. Минимальный возраст — 10 лет.', 'Пункт водных видов спорта на городском пляже, улица Шератон.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000019', 'fr', 'Stand-up paddle au lever ou au coucher du soleil', 'Une sortie guidée en paddle le long de la côte aux heures calmes, avec une courte pause baignade.', 'La mer est la plus plate tôt le matin et avant le coucher du soleil. Après quelques minutes d’entraînement sur le sable, votre guide vous emmène pour une balade tranquille le long de la côte, avec une pause pour nager et observer le récif peu profond.', 'Réglage de la planche et entraînement sur la plage
Paddle guidé le long de la côte
Pause baignade
Retour à la plage', 'Planche, pagaie et leash
Guide
Eau', 'Transfert depuis l’hôtel (option)
