insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000020', 'ar', 'يوم في الأكوا بارك', 'يوم كامل من الزحاليق وحمام الأمواج والنهر الهادئ، مع غداء ومشروبات.', 'يوم للعائلة كلها: زحاليق كبيرة للمراهقين والكبار، ومنطقة ألعاب مائية للصغار، ونهر هادئ وشيزلونجات في الظل. الغداء والمشروبات الغازية مشمولة.', '10:00 الدخول
وقت حر على الزحاليق والحمامات
13:00 الغداء
17:00 إغلاق الحديقة', 'تذكرة يوم كامل
غداء ومشروبات غازية
شيزلونجات وشماسي', 'التوصيل من الفندق (إضافة اختيارية)
الخزائن والمناشف', 'الأطفال أقل من 120 سم يستخدمون منطقة الأطفال.
بعض الزحاليق لها حدود للطول والوزن.', 'البوابة الرئيسية للأكوا بارك، طريق الغردقة–سفاجا. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000020', 'de', 'Aquapark-Tag mit Rutschen und Pools', 'Ein ganzer Tag mit Rutschen, Wellenbad und Lazy River, inklusive Mittagessen und Softdrinks.', 'Ein Tag für die ganze Familie: große Rutschen für Teenager und Erwachsene, ein Planschbereich für kleine Kinder, ein Lazy River und Liegen im Schatten. Mittagessen und Softdrinks sind inklusive.', '10:00 Einlass
Freie Zeit an Rutschen und Pools
13:00 Mittagessen
17:00 Der Park schließt', 'Tagesticket
Mittagessen und Softdrinks
Liegen und Sonnenschirme', 'Hoteltransfer (optional zubuchbar)
Schließfächer und Handtücher', 'Kinder unter 120 cm nutzen den Kinderbereich.
Für einige Rutschen gelten Größen- und Gewichtsgrenzen.', 'Haupteingang des Aquaparks, Straße Hurghada–Safaga. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000020', 'ru', 'День в аквапарке с горками и бассейнами', 'Целый день горок, бассейна с волнами и ленивой реки, с обедом и безалкогольными напитками.', 'День для всей семьи: большие горки для подростков и взрослых, игровая водная зона для малышей, ленивая река и лежаки в тени. Обед и безалкогольные напитки включены.', '10:00 вход
Свободное время на горках и в бассейнах
13:00 обед
17:00 закрытие парка', 'Входной билет на день
Обед и безалкогольные напитки
Лежаки и зонтики', 'Трансфер из отеля (дополнительная опция)
Шкафчики и полотенца', 'Дети ростом до 120 см пользуются детской зоной.
На некоторых горках есть ограничения по росту и весу.', 'Главный вход в аквапарк, трасса Хургада — Сафага. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000020', 'fr', 'Journée au parc aquatique : toboggans et piscines', 'Une journée entière de toboggans, piscine à vagues et rivière lente, avec déjeuner et boissons sans alcool.', 'Une journée pour toute la famille : grands toboggans pour les ados et les adultes, espace jeux d’eau pour les petits, rivière lente et transats à l’ombre. Le déjeuner et les boissons sans alcool sont inclus.', '10:00 entrée
