insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000021', 'ru', 'Конная прогулка по пляжу и пустыне', 'Два часа в седле от края пустыни до моря — для новичков и опытных наездников.', 'Отправляйтесь из конюшни по краю пустыни к тихому пляжу, где лошади идут по мелководью. Спокойные лошади для новичков и более резвые — для опытных наездников.', 'Знакомство с лошадьми и короткий урок
Прогулка по краю пустыни
Пляж и прогулка по воде
Возвращение в конюшню, чай', 'Лошадь и гид
Шлем
