insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000022', 'de', 'Dinner-Kreuzfahrt mit Musik', 'Drei Stunden auf dem abendlichen Meer: Sonnenuntergang, Abendbuffet und orientalische Livemusik an Deck.', 'Gehen Sie bei Sonnenuntergang an Bord und fahren Sie langsam die Küste entlang, während die Lichter von Hurghada angehen. Zum Abendessen gibt es ein Buffet mit Gegrilltem, Salaten und ägyptischen Gerichten; auf dem Oberdeck spielt eine Band.', '18:30 Einschiffen
