insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000022', 'ru', 'Круиз с ужином и музыкой', 'Три часа на вечернем море: закат, ужин «шведский стол» и живая восточная музыка на палубе.', 'Поднимитесь на борт на закате и неспешно плывите вдоль побережья, пока зажигаются огни Хургады. На ужин — «шведский стол» с блюдами на гриле, салатами и египетской кухней; на верхней палубе играет группа.', '18:30 посадка
19:00 отплытие на закате
