insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000022', 'fr', 'Croisière dîner en musique', 'Trois heures en mer le soir : coucher de soleil, dîner buffet et musique orientale live sur le pont.', 'Embarquez au coucher du soleil et naviguez lentement le long de la côte pendant que les lumières de Hurghada s’allument. Le dîner est un buffet de grillades, salades et plats égyptiens ; un groupe joue sur le pont supérieur.', '18:30 embarquement
