insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000023', 'de', 'Orientalische Nacht: Abendessen und Tanoura-Show', 'Ägyptisches Abendessen, ein Tanoura-Tänzer, Folkloremusik und ein Bummel durch einen laternenbeleuchteten Basar.', 'Ein Abend mit ägyptischer Musik und Küche. Nach einem Spaziergang durch einen kleinen Basar voller Laternen und Gewürze wird das Abendessen serviert, während sich ein Tanoura-Tänzer in seinen bunten Röcken dreht und eine Folkloreband spielt.', '19:00 Ankunft und Bummel durch den Basar
19:45 Abendessen
20:30 Tanoura-Show und Folkloremusik
