insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000023', 'ru', 'Восточная ночь: ужин и шоу танура', 'Египетский ужин, танцор танура, народная музыка и прогулка по базару, освещённому фонарями.', 'Вечер египетской музыки и кухни. После прогулки по небольшому базару с фонарями и специями подают ужин, а танцор танура кружится в своих разноцветных юбках под игру народного ансамбля.', '19:00 прибытие и прогулка по базару
19:45 ужин
20:30 шоу танура и народная музыка
22:00 окончание вечера', 'Ужин и безалкогольные напитки
