insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000024', 'en', 'Egyptian cooking class with a local family', 'Shop at the market, cook four classic dishes at home with a host family, then eat together.', 'Start at the local market to choose vegetables and spices, then cook in a family kitchen: stuffed vine leaves, koshari, baladi bread and a dessert. You eat what you cooked around the family table and take the recipes home.
Small group; the family confirms your date on request.', 'Meet your host at the market
Shopping for ingredients
Cooking four dishes together
Shared meal and recipes', 'Ingredients and cooking class
Meal and drinks
Recipe card', 'Hotel transfer (optional add-on)', 'Tell us about allergies or vegetarian needs when booking.', 'El Dahar vegetable market, main entrance. Pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000024', 'ar', 'درس طبخ مصري مع عائلة محلية', 'تسوّق من السوق، واطبخ أربعة أطباق مصرية مع عائلة مضيفة، ثم كُل معهم.', 'تبدأ من السوق المحلي لاختيار الخضار والتوابل، ثم تطبخ في مطبخ العائلة: محشي ورق عنب وكشري وعيش بلدي وحلو. تأكل ما طبخته على سفرة العائلة وتأخذ الوصفات معك.
مجموعة صغيرة؛ تؤكد العائلة موعدك بالطلب.', 'مقابلة المضيف في السوق
شراء المكونات
طبخ أربعة أطباق معًا
وجبة مشتركة والوصفات', 'المكونات ودرس الطبخ
الوجبة والمشروبات
بطاقة الوصفات', 'التوصيل من الفندق (إضافة اختيارية)', 'أخبرنا بأي حساسية أو نظام نباتي عند الحجز.', 'سوق الخضار بالدهار، المدخل الرئيسي. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000024', 'de', 'Ägyptischer Kochkurs bei einer einheimischen Familie', 'Einkaufen auf dem Markt, vier klassische Gerichte bei einer Gastfamilie kochen und anschließend gemeinsam essen.', 'Sie beginnen auf dem örtlichen Markt und wählen Gemüse und Gewürze aus, dann wird in einer Familienküche gekocht: gefüllte Weinblätter, Koshari, Baladi-Brot und ein Dessert. Was Sie gekocht haben, essen Sie am Familientisch, und die Rezepte nehmen Sie mit nach Hause.
Kleine Gruppe; die Familie bestätigt Ihren Termin auf Anfrage.', 'Treffen mit Ihren Gastgebern auf dem Markt
Einkauf der Zutaten
Gemeinsames Kochen von vier Gerichten
Gemeinsames Essen und Rezepte', 'Zutaten und Kochkurs
Essen und Getränke
Rezeptkarte', 'Hoteltransfer (optional zubuchbar)', 'Bitte teilen Sie uns bei der Buchung Allergien oder vegetarische Wünsche mit.', 'Gemüsemarkt El Dahar, Haupteingang. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000024', 'ru', 'Урок египетской кухни в местной семье', 'Закупитесь на рынке, приготовьте четыре классических блюда дома с принимающей семьёй, а затем поешьте вместе.', 'Начните с местного рынка, где вы выберете овощи и специи, а затем готовьте на семейной кухне: фаршированные виноградные листья, кошари, хлеб балади и десерт. Вы съедите приготовленное за семейным столом и заберёте рецепты домой.
Маленькая группа; семья подтверждает вашу дату по запросу.', 'Встреча с хозяевами на рынке
Покупка продуктов
Совместное приготовление четырёх блюд
Общая трапеза и рецепты', 'Продукты и кулинарный урок
Еда и напитки
Карточка с рецептами', 'Трансфер из отеля (дополнительная опция)', 'При бронировании сообщите нам об аллергиях или вегетарианском питании.', 'Овощной рынок Эль-Дахара, главный вход. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000024', 'fr', 'Cours de cuisine égyptienne chez une famille locale', 'Faites le marché, cuisinez quatre plats classiques chez une famille d’accueil, puis mangez ensemble.', 'Commencez au marché local pour choisir légumes et épices, puis cuisinez dans une cuisine familiale : feuilles de vigne farcies, koshari, pain baladi et un dessert. Vous dégustez ce que vous avez préparé autour de la table familiale et repartez avec les recettes.
Petit groupe ; la famille confirme votre date sur demande.', 'Rencontre avec votre hôte au marché
Achat des ingrédients
Préparation de quatre plats ensemble
Repas partagé et recettes', 'Ingrédients et cours de cuisine
Repas et boissons
Fiche recette', 'Transfert depuis l’hôtel (option)', 'Signalez vos allergies ou besoins végétariens lors de la réservation.', 'Marché aux légumes d’El Dahar, entrée principale. Localisation sur votre bon.', false, true);
