insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000025', 'en', 'Cairo and the Pyramids in one day', 'Early start by air-conditioned coach to the Pyramids of Giza, the Sphinx and the Egyptian Museum, with lunch.', 'A long but rewarding day. The coach leaves Hurghada before dawn and reaches Giza by late morning. Your Egyptologist guide takes you around the Pyramids and the Sphinx, then to the Egyptian Museum after lunch.
The operator confirms each request because seats on the coach and museum tickets are booked ahead.', '03:00 hotel pickup
09:30 Pyramids of Giza and the Sphinx
12:30 lunch
14:00 Egyptian Museum
16:30 drive back
23:00 back at your hotel', 'Coach with hotel pickup
Egyptologist guide
Entrance tickets
Lunch and water', 'Entry inside the Great Pyramid
Tips', 'Bring your passport. Comfortable shoes and a hat.
About 12 hours on the road in total.', 'Pickup from your hotel reception; the time is confirmed the day before.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000025', 'ar', 'القاهرة والأهرامات في يوم واحد', 'انطلاق مبكر بأتوبيس مكيف إلى أهرامات الجيزة وأبو الهول والمتحف المصري، مع الغداء.', 'يوم طويل لكنه يستحق. يتحرك الأتوبيس من الغردقة قبل الفجر ويصل الجيزة قبل الظهر. يرافقك مرشد أثري حول الأهرامات وأبو الهول، ثم إلى المتحف المصري بعد الغداء.
يؤكد المشغّل كل طلب لأن مقاعد الأتوبيس وتذاكر المتحف تُحجز مسبقًا.', '03:00 الاستلام من الفندق
09:30 أهرامات الجيزة وأبو الهول
12:30 الغداء
14:00 المتحف المصري
16:30 العودة
23:00 الوصول للفندق', 'أتوبيس مع الاستلام من الفندق
مرشد أثري
تذاكر الدخول
غداء ومياه', 'دخول الهرم الأكبر من الداخل
الإكراميات', 'أحضر جواز السفر. حذاء مريح وقبعة.
حوالي 12 ساعة طريق إجمالًا.', 'الاستلام من استقبال فندقك؛ يتأكد الموعد في اليوم السابق.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000025', 'de', 'Kairo und die Pyramiden an einem Tag', 'Früher Start im klimatisierten Reisebus zu den Pyramiden von Gizeh, der Sphinx und dem Ägyptischen Museum, mit Mittagessen.', 'Ein langer, aber lohnender Tag. Der Bus verlässt Hurghada vor Sonnenaufgang und erreicht Gizeh am späten Vormittag. Ihr Ägyptologe führt Sie zu den Pyramiden und der Sphinx und nach dem Mittagessen ins Ägyptische Museum.
Der Anbieter bestätigt jede Anfrage einzeln, da Busplätze und Museumstickets im Voraus gebucht werden.', '03:00 Abholung vom Hotel
09:30 Pyramiden von Gizeh und Sphinx
12:30 Mittagessen
14:00 Ägyptisches Museum
16:30 Rückfahrt
23:00 Zurück in Ihrem Hotel', 'Reisebus mit Abholung vom Hotel
Ägyptologe als Guide
Eintrittskarten
Mittagessen und Wasser', 'Eintritt ins Innere der Großen Pyramide
Trinkgelder', 'Bitte Reisepass mitbringen. Bequeme Schuhe und eine Kopfbedeckung.
Insgesamt etwa 12 Stunden Fahrt.', 'Abholung an Ihrer Hotelrezeption; die Uhrzeit wird am Vortag bestätigt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000025', 'ru', 'Каир и пирамиды за один день', 'Ранний выезд на автобусе с кондиционером к пирамидам Гизы, Сфинксу и Египетскому музею, с обедом.', 'Долгий, но насыщенный день. Автобус выезжает из Хургады до рассвета и к концу утра прибывает в Гизу. Гид-египтолог проведёт вас к пирамидам и Сфинксу, а после обеда — в Египетский музей.
Оператор подтверждает каждую заявку, потому что места в автобусе и билеты в музей бронируются заранее.', '03:00 выезд из отеля
09:30 пирамиды Гизы и Сфинкс
12:30 обед
14:00 Египетский музей
16:30 обратная дорога
23:00 возвращение в отель', 'Автобус с трансфером из отеля
Гид-египтолог
Входные билеты
Обед и вода', 'Вход внутрь пирамиды Хеопса
Чаевые', 'Возьмите с собой паспорт. Удобная обувь и головной убор.
Всего около 12 часов в дороге.', 'Трансфер от ресепшена вашего отеля; время подтверждается накануне.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000025', 'fr', 'Le Caire et les Pyramides en une journée', 'Départ matinal en car climatisé vers les Pyramides de Gizeh, le Sphinx et le Musée égyptien, avec déjeuner.', 'Une longue journée, mais qui en vaut la peine. Le car quitte Hurghada avant l’aube et arrive à Gizeh en fin de matinée. Votre guide égyptologue vous fait découvrir les Pyramides et le Sphinx, puis le Musée égyptien après le déjeuner.
Le prestataire confirme chaque demande, car les places dans le car et les billets du musée sont réservés à l’avance.', '03:00 prise en charge à l’hôtel
09:30 Pyramides de Gizeh et Sphinx
12:30 déjeuner
14:00 Musée égyptien
16:30 trajet retour
23:00 retour à votre hôtel', 'Car avec prise en charge à l’hôtel
Guide égyptologue
Billets d’entrée
Déjeuner et eau', 'Entrée à l’intérieur de la Grande Pyramide
Pourboires', 'Apportez votre passeport. Chaussures confortables et chapeau.
Environ 12 heures de route au total.', 'Prise en charge à la réception de votre hôtel ; l’heure est confirmée la veille.', false, true);
