insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000026', 'en', 'Luxor hot-air balloon at sunrise and the West Bank', 'Float over the Valley of the Kings at dawn, then visit the tombs and Hatshepsut''s temple.', 'Leave Hurghada in the night to reach Luxor before dawn. As the sun rises your balloon drifts over the Nile, the fields and the West Bank temples. After landing, your guide takes you to the Valley of the Kings and the Temple of Hatshepsut, with lunch by the Nile.
Balloon flights depend on the wind and are confirmed by the operator.', '01:00 hotel pickup
05:30 balloon take-off (about 45 minutes)
08:00 Valley of the Kings
10:30 Temple of Hatshepsut
12:30 lunch
13:30 drive back
18:30 back at your hotel', 'Coach with hotel pickup
Balloon flight
Guide and entrance tickets
Lunch', 'Special tombs (extra ticket)
Tips', 'Minimum age 7.
If the balloon cannot fly, you get the balloon part refunded.', 'Pickup from your hotel reception; the time is confirmed the day before.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000026', 'ar', 'منطاد الأقصر عند الشروق والبر الغربي', 'حلّق فوق وادي الملوك عند الفجر، ثم زُر المقابر ومعبد حتشبسوت.', 'تتحرك من الغردقة ليلًا لتصل الأقصر قبل الفجر. ومع شروق الشمس يطفو المنطاد فوق النيل والحقول ومعابد البر الغربي. وبعد الهبوط يأخذك المرشد إلى وادي الملوك ومعبد حتشبسوت، مع غداء على النيل.
رحلات المنطاد تعتمد على الرياح ويؤكدها المشغّل.', '01:00 الاستلام من الفندق
05:30 إقلاع المنطاد (حوالي 45 دقيقة)
08:00 وادي الملوك
10:30 معبد حتشبسوت
12:30 الغداء
13:30 العودة
18:30 الوصول للفندق', 'أتوبيس مع الاستلام من الفندق
رحلة المنطاد
المرشد وتذاكر الدخول
الغداء', 'المقابر الخاصة (تذكرة إضافية)
الإكراميات', 'الحد الأدنى للسن 7 سنوات.
إذا لم يطر المنطاد يُسترد ثمن جزء المنطاد.', 'الاستلام من استقبال فندقك؛ يتأكد الموعد في اليوم السابق.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000026', 'de', 'Heißluftballon bei Sonnenaufgang in Luxor und die Westbank', 'Schweben Sie im Morgengrauen über das Tal der Könige und besuchen Sie danach die Gräber und den Tempel der Hatschepsut.', 'Sie verlassen Hurghada in der Nacht, um Luxor vor Sonnenaufgang zu erreichen. Während die Sonne aufgeht, gleitet Ihr Ballon über den Nil, die Felder und die Tempel der Westbank. Nach der Landung führt Sie Ihr Guide ins Tal der Könige und zum Tempel der Hatschepsut, mit Mittagessen am Nil.
Ballonfahrten sind windabhängig und werden vom Anbieter bestätigt.', '01:00 Abholung vom Hotel
05:30 Start des Ballons (etwa 45 Minuten)
08:00 Tal der Könige
10:30 Tempel der Hatschepsut
12:30 Mittagessen
13:30 Rückfahrt
18:30 Zurück in Ihrem Hotel', 'Reisebus mit Abholung vom Hotel
Ballonfahrt
Guide und Eintrittskarten
Mittagessen', 'Besondere Gräber (Extraticket)
Trinkgelder', 'Mindestalter 7 Jahre.
Falls der Ballon nicht starten kann, wird Ihnen der Ballonanteil erstattet.', 'Abholung an Ihrer Hotelrezeption; die Uhrzeit wird am Vortag bestätigt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000026', 'ru', 'Луксор: воздушный шар на рассвете и Западный берег', 'Пролетите над Долиной царей на рассвете, а затем посетите гробницы и храм Хатшепсут.', 'Вы выезжаете из Хургады ночью, чтобы добраться до Луксора до рассвета. С восходом солнца ваш шар плывёт над Нилом, полями и храмами Западного берега. После приземления гид проведёт вас по Долине царей и храму Хатшепсут, а обед будет на берегу Нила.
Полёты на шаре зависят от ветра и подтверждаются оператором.', '01:00 выезд из отеля
05:30 взлёт воздушного шара (около 45 минут)
08:00 Долина царей
10:30 храм Хатшепсут
12:30 обед
13:30 обратная дорога
18:30 возвращение в отель', 'Автобус с трансфером из отеля
Полёт на воздушном шаре
Гид и входные билеты
Обед', 'Особые гробницы (отдельный билет)
Чаевые', 'Минимальный возраст — 7 лет.
Если шар не сможет взлететь, стоимость полёта вам вернут.', 'Трансфер от ресепшена вашего отеля; время подтверждается накануне.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000026', 'fr', 'Montgolfière au lever du soleil à Louxor et rive ouest', 'Survolez la Vallée des Rois à l’aube, puis visitez les tombes et le temple d’Hatchepsout.', 'Quittez Hurghada dans la nuit pour arriver à Louxor avant l’aube. Au lever du soleil, votre montgolfière dérive au-dessus du Nil, des champs et des temples de la rive ouest. Après l’atterrissage, votre guide vous emmène à la Vallée des Rois et au temple d’Hatchepsout, avec déjeuner au bord du Nil.
Les vols en montgolfière dépendent du vent et sont confirmés par le prestataire.', '01:00 prise en charge à l’hôtel
05:30 décollage de la montgolfière (environ 45 minutes)
08:00 Vallée des Rois
10:30 temple d’Hatchepsout
12:30 déjeuner
13:30 trajet retour
18:30 retour à votre hôtel', 'Car avec prise en charge à l’hôtel
Vol en montgolfière
Guide et billets d’entrée
Déjeuner', 'Tombes spéciales (billet en supplément)
Pourboires', 'Âge minimum : 7 ans.
Si la montgolfière ne peut pas voler, la partie vol vous est remboursée.', 'Prise en charge à la réception de votre hôtel ; l’heure est confirmée la veille.', false, true);
