insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000027', 'en', 'Hammam and massage ritual', 'Steam, black-soap scrub, foam wash and a 45-minute oil massage, then mint tea.', 'Two hours of slow time. You start in the steam room, then a therapist scrubs and washes you with foam on the warm marble, followed by a 45-minute massage with argan oil. Finish with mint tea in the rest room.', 'Steam room
Black-soap scrub and foam wash
45-minute oil massage
Rest with mint tea', 'Hammam and massage
Towels, robe and slippers
Mint tea', 'Hotel transfer (optional add-on)', 'Minimum age 16. Tell us about pregnancy or health conditions.', 'Spa reception, Sahl Hasheesh old town. Pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000027', 'ar', 'طقوس الحمام الشرقي والمساج', 'بخار، وتقشير بالصابون الأسود، وغسيل بالرغوة، ومساج بالزيت 45 دقيقة، ثم شاي بالنعناع.', 'ساعتان من الهدوء. تبدأ في غرفة البخار، ثم يقشّرك المعالج ويغسلك بالرغوة على الرخام الدافئ، يليه مساج 45 دقيقة بزيت الأرجان. وتختم بشاي النعناع في غرفة الاسترخاء.', 'غرفة البخار
تقشير بالصابون الأسود وغسيل بالرغوة
مساج بالزيت 45 دقيقة
استرخاء مع شاي النعناع', 'الحمام والمساج
مناشف وروب وشبشب
شاي بالنعناع', 'التوصيل من الفندق (إضافة اختيارية)', 'الحد الأدنى للسن 16 عامًا. أخبرنا عن الحمل أو أي حالة صحية.', 'استقبال السبا، المدينة القديمة بسهل حشيش. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000027', 'de', 'Hammam- und Massageritual', 'Dampfbad, Peeling mit schwarzer Seife, Schaumwäsche und eine 45-minütige Ölmassage, danach Minztee.', 'Zwei Stunden zum Entschleunigen. Sie beginnen im Dampfbad, dann werden Sie auf dem warmen Marmor gepeelt und mit Schaum gewaschen, gefolgt von einer 45-minütigen Massage mit Arganöl. Zum Abschluss gibt es Minztee im Ruheraum.', 'Dampfbad
Peeling mit schwarzer Seife und Schaumwäsche
45-minütige Ölmassage
Ruhepause mit Minztee', 'Hammam und Massage
Handtücher, Bademantel und Hausschuhe
Minztee', 'Hoteltransfer (optional zubuchbar)', 'Mindestalter 16 Jahre. Bitte informieren Sie uns über eine Schwangerschaft oder gesundheitliche Beschwerden.', 'Spa-Rezeption, Altstadt von Sahl Hasheesh. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000027', 'ru', 'Ритуал хаммама и массажа', 'Парная, пилинг с чёрным мылом, пенное мытьё и 45-минутный массаж с маслом, а затем мятный чай.', 'Два часа неспешного отдыха. Вы начинаете в парной, затем мастер делает вам пилинг и пенное мытьё на тёплом мраморе, после чего следует 45-минутный массаж с аргановым маслом. В завершение — мятный чай в комнате отдыха.', 'Парная
Пилинг с чёрным мылом и пенное мытьё
45-минутный массаж с маслом
Отдых с мятным чаем', 'Хаммам и массаж
Полотенца, халат и тапочки
Мятный чай', 'Трансфер из отеля (дополнительная опция)', 'Минимальный возраст — 16 лет. Сообщите нам о беременности или проблемах со здоровьем.', 'Ресепшен спа, старый город Сахл-Хашиша. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000027', 'fr', 'Rituel hammam et massage', 'Bain de vapeur, gommage au savon noir, lavage à la mousse et massage à l’huile de 45 minutes, puis thé à la menthe.', 'Deux heures pour prendre son temps. Vous commencez par le bain de vapeur, puis un praticien vous gomme et vous lave à la mousse sur le marbre chaud, avant un massage de 45 minutes à l’huile d’argan. Pour finir, un thé à la menthe dans la salle de repos.', 'Bain de vapeur
Gommage au savon noir et lavage à la mousse
Massage à l’huile de 45 minutes
Détente avec un thé à la menthe', 'Hammam et massage
Serviettes, peignoir et chaussons
Thé à la menthe', 'Transfert depuis l’hôtel (option)', 'Âge minimum : 16 ans. Informez-nous en cas de grossesse ou de problème de santé.', 'Accueil du spa, vieille ville de Sahl Hasheesh. Localisation sur votre bon.', false, true);
