insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000028', 'en', 'Beach yoga at sunrise or sunset', 'A 75-minute gentle yoga class on the sand, for all levels, followed by fresh juice.', 'A calm class led by a certified teacher on a quiet beach in Sahl Hasheesh. Breathing, gentle flow and a long relaxation to the sound of the sea. Mats are provided.', 'Welcome and breathing
Gentle flow
Relaxation
Fresh juice', 'Yoga class with certified teacher
Mat and towel
Fresh juice', 'Hotel transfer (optional add-on)', 'All levels welcome. Tell the teacher about injuries.', 'Spa beach deck, Sahl Hasheesh. Pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000028', 'ar', 'يوجا على الشاطئ عند الشروق أو الغروب', 'حصة يوجا هادئة 75 دقيقة على الرمل لكل المستويات، يليها عصير طازج.', 'حصة هادئة مع مدربة معتمدة على شاطئ هادئ في سهل حشيش. تنفّس وحركات لطيفة واسترخاء طويل على صوت البحر. الحصائر متوفرة.', 'ترحيب وتمارين تنفس
حركات لطيفة
استرخاء
عصير طازج', 'حصة يوجا مع مدربة معتمدة
حصيرة ومنشفة
عصير طازج', 'التوصيل من الفندق (إضافة اختيارية)', 'مناسبة لكل المستويات. أخبر المدربة بأي إصابة.', 'منصة السبا على الشاطئ، سهل حشيش. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000028', 'de', 'Strand-Yoga bei Sonnenaufgang oder Sonnenuntergang', 'Eine 75-minütige sanfte Yogastunde im Sand für alle Niveaus, danach frischer Saft.', 'Eine ruhige Stunde mit einer zertifizierten Lehrkraft an einem stillen Strand in Sahl Hasheesh. Atemübungen, sanfter Flow und eine lange Entspannung zum Rauschen des Meeres. Matten werden gestellt.', 'Begrüßung und Atemübungen
Sanfter Flow
Entspannung
Frischer Saft', 'Yogastunde mit zertifizierter Lehrkraft
Matte und Handtuch
Frischer Saft', 'Hoteltransfer (optional zubuchbar)', 'Alle Niveaus willkommen. Informieren Sie die Lehrkraft über Verletzungen.', 'Strandterrasse des Spas, Sahl Hasheesh. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000028', 'ru', 'Йога на пляже на рассвете или на закате', '75-минутное мягкое занятие йогой на песке для любого уровня, а после — свежевыжатый сок.', 'Спокойное занятие с сертифицированным преподавателем на тихом пляже в Сахл-Хашише. Дыхательные упражнения, мягкая практика и долгое расслабление под шум моря. Коврики предоставляются.', 'Знакомство и дыхательные упражнения
Мягкая практика
Расслабление
Свежевыжатый сок', 'Занятие йогой с сертифицированным преподавателем
Коврик и полотенце
Свежевыжатый сок', 'Трансфер из отеля (дополнительная опция)', 'Подходит для любого уровня. Расскажите преподавателю о травмах.', 'Пляжная площадка спа, Сахл-Хашиш. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000028', 'fr', 'Yoga sur la plage au lever ou au coucher du soleil', 'Un cours de yoga doux de 75 minutes sur le sable, pour tous les niveaux, suivi d’un jus frais.', 'Un cours tranquille animé par un professeur certifié sur une plage paisible de Sahl Hasheesh. Respiration, enchaînement doux et longue relaxation au son de la mer. Les tapis sont fournis.', 'Accueil et respiration
Enchaînement doux
Relaxation
Jus frais', 'Cours de yoga avec professeur certifié
Tapis et serviette
Jus frais', 'Transfert depuis l’hôtel (option)', 'Tous niveaux bienvenus. Signalez vos blessures au professeur.', 'Terrasse de plage du spa, Sahl Hasheesh. Localisation sur votre bon.', false, true);
