insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000029', 'en', 'Snorkelling day at two coral reefs', 'A relaxed boat day with two snorkelling stops, a beach break and lunch on board.', 'Sail out to the reefs off Hurghada with a small crew. At each stop the guide leads a group in the water while others relax on deck. Between the reefs the boat anchors near a white-sand beach for swimming and lunch.
Good for first-time snorkellers: vests and masks in all sizes are on board.', '08:30 boat leaves the marina
10:00 first reef
12:00 beach stop and lunch
14:00 second reef
16:00 back at the marina', 'Boat, crew and guide
Mask, snorkel, fins and vest
Lunch, water and soft drinks', 'Hotel transfer (optional add-on)
Marine park fee
Tips', 'Children must wear a vest in the water.
Use reef-safe sun cream.', 'Hurghada New Marina, gate 2, 20 minutes before departure.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000029', 'ar', 'يوم سنوركل على شعبتين', 'يوم هادئ بالمركب مع وقفتين للسنوركل واستراحة على شاطئ وغداء على المركب.', 'تبحر إلى شعاب الغردقة مع طاقم صغير. في كل وقفة ينزل المرشد مع مجموعة إلى الماء، والباقي يسترخي على السطح. بين الشعبتين يرسو المركب قرب شاطئ رملي أبيض للسباحة والغداء.
مناسب لمن يجرّب السنوركل لأول مرة: سترات ونظارات بكل المقاسات على المركب.', '08:30 تحرك المركب من المارينا
10:00 الشعبة الأولى
12:00 وقفة الشاطئ والغداء
14:00 الشعبة الثانية
16:00 العودة للمارينا', 'المركب والطاقم والمرشد
نظارة وسنوركل وزعانف وسترة
غداء ومياه ومشروبات', 'التوصيل من الفندق (إضافة اختيارية)
رسوم المحمية
الإكراميات', 'الأطفال يلبسون السترة في الماء.
استخدم واقي شمس آمن للشعاب.', 'مارينا الغردقة الجديدة، البوابة 2، قبل الموعد بـ 20 دقيقة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000029', 'de', 'Schnorcheltag an zwei Korallenriffen', 'Ein entspannter Bootstag mit zwei Schnorchelstopps, einer Strandpause und Mittagessen an Bord.', 'Fahren Sie mit einer kleinen Crew hinaus zu den Riffen vor Hurghada. An jedem Stopp führt der Guide eine Gruppe im Wasser, während die anderen an Deck entspannen. Zwischen den Riffen ankert das Boot vor einem weißen Sandstrand zum Baden und Mittagessen.
Ideal für alle, die zum ersten Mal schnorcheln: Westen und Masken in allen Größen sind an Bord.', '08:30 Das Boot verlässt die Marina
10:00 Erstes Riff
12:00 Strandstopp und Mittagessen
14:00 Zweites Riff
16:00 Zurück an der Marina', 'Boot, Crew und Guide
Maske, Schnorchel, Flossen und Weste
Mittagessen, Wasser und Softdrinks', 'Hoteltransfer (optional zubuchbar)
Meeresparkgebühr
Trinkgelder', 'Kinder müssen im Wasser eine Weste tragen.
Verwenden Sie riffschonende Sonnencreme.', 'Hurghada New Marina, Tor 2, 20 Minuten vor Abfahrt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000029', 'ru', 'Снорклинг на двух коралловых рифах', 'Расслабленный день на лодке: две остановки для снорклинга, отдых на пляже и обед на борту.', 'Отправляйтесь к рифам у берегов Хургады с небольшой командой. На каждой остановке гид ведёт группу в воде, а остальные отдыхают на палубе. Между рифами лодка встаёт на якорь у пляжа с белым песком, где можно искупаться и пообедать.
Подходит для тех, кто впервые пробует снорклинг: на борту есть жилеты и маски всех размеров.', '08:30 отправление лодки из марины
10:00 первый риф
12:00 остановка на пляже и обед
14:00 второй риф
16:00 возвращение в марину', 'Лодка, команда и гид
Маска, трубка, ласты и жилет
Обед, вода и безалкогольные напитки', 'Трансфер из отеля (дополнительная опция)
Сбор морского парка
Чаевые', 'Дети должны быть в воде в жилете.
Используйте солнцезащитный крем, безопасный для рифов.', 'Новая марина Хургады, ворота 2, за 20 минут до отправления.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000029', 'fr', 'Journée snorkeling sur deux récifs coralliens', 'Une journée détendue en bateau avec deux arrêts snorkeling, une pause plage et le déjeuner à bord.', 'Partez vers les récifs au large de Hurghada avec un petit équipage. À chaque arrêt, le guide accompagne un groupe dans l’eau pendant que d’autres se détendent sur le pont. Entre les récifs, le bateau jette l’ancre près d’une plage de sable blanc pour la baignade et le déjeuner.
Idéal pour un premier snorkeling : gilets et masques de toutes tailles à bord.', '08:30 départ du bateau depuis la marina
10:00 premier récif
12:00 pause plage et déjeuner
14:00 deuxième récif
16:00 retour à la marina', 'Bateau, équipage et guide
Masque, tuba, palmes et gilet
Déjeuner, eau et boissons sans alcool', 'Transfert depuis l’hôtel (option)
Taxe du parc marin
Pourboires', 'Les enfants doivent porter un gilet dans l’eau.
Utilisez une crème solaire sans danger pour les récifs.', 'Hurghada New Marina, porte 2, 20 minutes avant le départ.', false, true);
