insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000030', 'en', 'Hurghada city tour: mosque, church and marina', 'Four hours with a local guide through the city''s landmarks, old streets and the marina.', 'See the Hurghada most visitors miss. Your guide shows you the big mosque of El Dahar, the Coptic church, the fish market and the busy streets of the old town, then ends with a walk along the marina.
Modest clothes are needed to enter the mosque; scarves are provided.', 'Pickup or meeting point
El Dahar mosque
Coptic church
Fish market and old streets
Marina walk and free time', 'Local guide
Air-conditioned minibus
Water', 'Hotel transfer (optional add-on)
Shopping
Tips', 'Shoulders and knees covered for the mosque.', 'El Dahar main square, in front of the old post office.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000030', 'ar', 'جولة في مدينة الغردقة: الجامع والكنيسة والمارينا', 'أربع ساعات مع مرشد محلي بين معالم المدينة وشوارعها القديمة والمارينا.', 'اكتشف الغردقة التي لا يراها أغلب الزوار. يأخذك المرشد إلى الجامع الكبير في الدهار، والكنيسة القبطية، وسوق السمك، وشوارع المدينة القديمة، ثم تنتهي الجولة بتمشية على المارينا.
ملابس محتشمة مطلوبة لدخول الجامع، والأوشحة متوفرة.', 'الاستلام أو نقطة اللقاء
جامع الدهار
الكنيسة القبطية
سوق السمك والشوارع القديمة
تمشية على المارينا ووقت حر', 'مرشد محلي
ميني باص مكيف
مياه', 'التوصيل من الفندق (إضافة اختيارية)
التسوق
الإكراميات', 'تغطية الكتفين والركبتين لدخول الجامع.', 'ميدان الدهار الرئيسي، أمام مكتب البريد القديم.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000030', 'de', 'Stadtrundfahrt Hurghada: Moschee, Kirche und Marina', 'Vier Stunden mit einem einheimischen Guide zu den Sehenswürdigkeiten, den alten Gassen und der Marina.', 'Entdecken Sie das Hurghada, das die meisten Besucher verpassen. Ihr Guide zeigt Ihnen die große Moschee von El Dahar, die koptische Kirche, den Fischmarkt und die belebten Straßen der Altstadt; zum Abschluss spazieren Sie an der Marina entlang.
Für den Besuch der Moschee ist angemessene Kleidung nötig; Tücher werden gestellt.', 'Abholung oder Treffpunkt
El-Dahar-Moschee
Koptische Kirche
Fischmarkt und alte Gassen
Spaziergang an der Marina und freie Zeit', 'Einheimischer Guide
Klimatisierter Minibus
Wasser', 'Hoteltransfer (optional zubuchbar)
Einkäufe
Trinkgelder', 'Schultern und Knie müssen für die Moschee bedeckt sein.', 'Hauptplatz von El Dahar, vor dem alten Postamt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000030', 'ru', 'Обзорная экскурсия по Хургаде: мечеть, церковь и марина', 'Четыре часа с местным гидом по достопримечательностям города, старым улочкам и марине.', 'Увидьте Хургаду, которую пропускает большинство туристов. Гид покажет вам большую мечеть Эль-Дахара, коптскую церковь, рыбный рынок и оживлённые улицы старого города, а в конце вас ждёт прогулка по марине.
Для входа в мечеть нужна закрытая одежда; платки выдаются.', 'Трансфер или место встречи
Мечеть Эль-Дахар
Коптская церковь
Рыбный рынок и старые улочки
Прогулка по марине и свободное время', 'Местный гид
Микроавтобус с кондиционером
Вода', 'Трансфер из отеля (дополнительная опция)
Покупки
Чаевые', 'Для посещения мечети плечи и колени должны быть закрыты.', 'Главная площадь Эль-Дахара, напротив старого почтового отделения.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000030', 'fr', 'Visite de Hurghada : mosquée, église et marina', 'Quatre heures avec un guide local à travers les monuments de la ville, ses vieilles rues et la marina.', 'Découvrez le Hurghada que la plupart des visiteurs ne voient pas. Votre guide vous montre la grande mosquée d’El Dahar, l’église copte, le marché aux poissons et les rues animées de la vieille ville, puis termine par une promenade le long de la marina.
Une tenue correcte est exigée pour entrer dans la mosquée ; des foulards sont fournis.', 'Prise en charge ou point de rendez-vous
Mosquée d’El Dahar
Église copte
Marché aux poissons et vieilles rues
Promenade sur la marina et temps libre', 'Guide local
Minibus climatisé
Eau', 'Transfert depuis l’hôtel (option)
Achats
Pourboires', 'Épaules et genoux couverts pour la mosquée.', 'Place principale d’El Dahar, devant l’ancienne poste.', false, true);
