insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000032', 'en', 'Submarine trip to the coral reef', 'Dive about 20 metres in a real tourist submarine and watch the reef through big windows, without getting wet.', 'Perfect for families and non-swimmers. A shuttle boat takes you to the submarine, which then dives slowly along the reef. Every seat has its own window, and a guide explains the fish and corals you see.', 'Shuttle boat to the submarine
About 45 minutes under water
Shuttle back to the marina', 'Shuttle boat and submarine dive
Guide on board
Water', 'Hotel transfer (optional add-on)
Photos', 'Not suitable for people with strong fear of enclosed spaces.', 'Hurghada New Marina, submarine pier, 30 minutes before departure.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000032', 'ar', 'رحلة الغواصة إلى الشعاب', 'انزل حوالي 20 مترًا في غواصة سياحية حقيقية وشاهد الشعاب من نوافذ كبيرة دون أن تبتل.', 'مثالية للعائلات ولمن لا يسبح. يأخذك قارب صغير إلى الغواصة، ثم تغوص ببطء بجوار الشعاب. لكل مقعد نافذة خاصة، ويشرح المرشد الأسماك والشعاب التي تراها.', 'قارب إلى الغواصة
حوالي 45 دقيقة تحت الماء
العودة للمارينا', 'القارب والغوص بالغواصة
مرشد على متنها
مياه', 'التوصيل من الفندق (إضافة اختيارية)
الصور', 'غير مناسبة لمن يخاف الأماكن المغلقة بشدة.', 'مارينا الغردقة الجديدة، رصيف الغواصة، قبل الموعد بـ 30 دقيقة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000032', 'de', 'U-Boot-Fahrt zum Korallenriff', 'Tauchen Sie in einem echten Touristen-U-Boot etwa 20 Meter tief und beobachten Sie das Riff durch große Fenster, ohne nass zu werden.', 'Perfekt für Familien und Nichtschwimmer. Ein Zubringerboot bringt Sie zum U-Boot, das dann langsam am Riff entlang abtaucht. Jeder Platz hat ein eigenes Fenster, und ein Guide erklärt Ihnen die Fische und Korallen, die Sie sehen.', 'Zubringerboot zum U-Boot
Etwa 45 Minuten unter Wasser
Zubringer zurück zur Marina', 'Zubringerboot und U-Boot-Tauchgang
Guide an Bord
Wasser', 'Hoteltransfer (optional zubuchbar)
Fotos', 'Nicht geeignet für Personen mit starker Platzangst.', 'Hurghada New Marina, U-Boot-Anleger, 30 Minuten vor Abfahrt.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000032', 'ru', 'Прогулка на подводной лодке к коралловому рифу', 'Опуститесь примерно на 20 метров на настоящей туристической подводной лодке и смотрите на риф через большие иллюминаторы, не намокнув.', 'Идеально для семей и тех, кто не умеет плавать. Катер доставит вас к подводной лодке, которая медленно погружается вдоль рифа. У каждого места свой иллюминатор, а гид рассказывает о рыбах и кораллах, которых вы видите.', 'Катер до подводной лодки
Около 45 минут под водой
Катер обратно в марину', 'Катер-трансфер и погружение на подводной лодке
Гид на борту
Вода', 'Трансфер из отеля (дополнительная опция)
Фотографии', 'Не подходит людям с сильной боязнью замкнутых пространств.', 'Новая марина Хургады, причал подводной лодки, за 30 минут до отправления.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000032', 'fr', 'Sortie en sous-marin jusqu’au récif corallien', 'Descendez à environ 20 mètres dans un vrai sous-marin touristique et observez le récif par de grands hublots, sans vous mouiller.', 'Idéal pour les familles et les personnes qui ne nagent pas. Un bateau navette vous conduit au sous-marin, qui plonge ensuite lentement le long du récif. Chaque siège a son propre hublot, et un guide vous présente les poissons et les coraux que vous voyez.', 'Bateau navette jusqu’au sous-marin
Environ 45 minutes sous l’eau
Navette retour vers la marina', 'Bateau navette et plongée en sous-marin
Guide à bord
Eau', 'Transfert depuis l’hôtel (option)
Photos', 'Déconseillé aux personnes très claustrophobes.', 'Hurghada New Marina, ponton du sous-marin, 30 minutes avant le départ.', false, true);
