insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000033', 'en', 'Night dive on the house reef', 'A guided dive after sunset with torches, when the reef''s night life comes out.', 'At night the reef changes completely: octopus and moray eels hunt, parrotfish sleep in their bubbles and the plankton glows. You dive with an experienced guide and a torch, in a calm and shallow area.
The centre checks your experience before confirming.', '17:30 check-in and briefing
18:15 equipment and entry
18:30 night dive (about 45 minutes)
19:30 hot drink and log', 'Guided night dive
Torch, tank, weights and full equipment
Hot drink', 'Hotel transfer (optional add-on)', 'Open Water certificate and at least 10 logged dives.
Minimum age 15.', 'Dive centre on Sheraton Road. Exact pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000033', 'ar', 'غطسة ليلية على الشعاب', 'غطسة مع مرشد بعد الغروب بالكشافات، عندما تبدأ حياة الشعاب الليلية.', 'في الليل تتغير الشعاب تمامًا: الأخطبوط وثعابين الموراي تصطاد، وأسماك الببغاء تنام داخل فقاعاتها، والعوالق تتوهج. تغوص مع مرشد خبير وكشاف في منطقة هادئة وضحلة.
يراجع المركز خبرتك قبل التأكيد.', '17:30 التسجيل والشرح
18:15 المعدات والنزول
18:30 الغطسة الليلية (حوالي 45 دقيقة)
19:30 مشروب ساخن وتسجيل الغطسة', 'غطسة ليلية مع مرشد
كشاف وأسطوانة وأوزان ومعدات كاملة
مشروب ساخن', 'التوصيل من الفندق (إضافة اختيارية)', 'شهادة Open Water و10 غطسات مسجلة على الأقل.
الحد الأدنى للسن 15 عامًا.', 'مركز غوص على طريق الشيراتون. الموقع الدقيق في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000033', 'de', 'Nachttauchgang am Hausriff', 'Ein geführter Tauchgang nach Sonnenuntergang mit Lampen, wenn das nächtliche Leben am Riff erwacht.', 'Nachts verwandelt sich das Riff völlig: Oktopusse und Muränen gehen auf Jagd, Papageifische schlafen in ihren Schleimkokons und das Plankton leuchtet. Sie tauchen mit einem erfahrenen Guide und einer Lampe in einem ruhigen, flachen Bereich.
Das Tauchzentrum prüft vor der Bestätigung Ihre Erfahrung.', '17:30 Check-in und Briefing
18:15 Ausrüstung und Einstieg
18:30 Nachttauchgang (etwa 45 Minuten)
19:30 Heißgetränk und Logbuch', 'Geführter Nachttauchgang
Lampe, Flasche, Blei und komplette Ausrüstung
Heißgetränk', 'Hoteltransfer (optional zubuchbar)', 'Open-Water-Brevet und mindestens 10 geloggte Tauchgänge.
Mindestalter 15 Jahre.', 'Tauchzentrum an der Sheraton Road. Genauer Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000033', 'ru', 'Ночное погружение на домашнем рифе', 'Погружение с гидом после заката, с фонарями, когда на рифе начинается ночная жизнь.', 'Ночью риф полностью меняется: осьминоги и мурены выходят на охоту, рыбы-попугаи спят в своих коконах, а планктон светится. Вы погружаетесь с опытным гидом и фонарём в спокойном мелководном месте.
Перед подтверждением центр проверяет ваш опыт.', '17:30 регистрация и брифинг
18:15 снаряжение и вход в воду
18:30 ночное погружение (около 45 минут)
19:30 горячий напиток и запись в логбук', 'Ночное погружение с гидом
Фонарь, баллон, грузы и полное снаряжение
Горячий напиток', 'Трансфер из отеля (дополнительная опция)', 'Сертификат Open Water и не менее 10 записанных в логбук погружений.
Минимальный возраст — 15 лет.', 'Дайвинг-центр на улице Шератон. Точная точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000033', 'fr', 'Plongée de nuit sur le récif de l’hôtel', 'Une plongée guidée après le coucher du soleil, à la lampe, quand la vie nocturne du récif se réveille.', 'La nuit, le récif change complètement : poulpes et murènes chassent, les poissons-perroquets dorment dans leur bulle et le plancton brille. Vous plongez avec un guide expérimenté et une lampe, dans une zone calme et peu profonde.
Le centre vérifie votre expérience avant de confirmer.', '17:30 accueil et briefing
18:15 équipement et mise à l’eau
18:30 plongée de nuit (environ 45 minutes)
19:30 boisson chaude et carnet de plongée', 'Plongée de nuit guidée
Lampe, bouteille, plombs et équipement complet
Boisson chaude', 'Transfert depuis l’hôtel (option)', 'Niveau Open Water et au moins 10 plongées enregistrées.
Âge minimum : 15 ans.', 'Centre de plongée sur Sheraton Road. Localisation exacte sur votre bon.', false, true);
