insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000034', 'en', 'Flyboard session over the sea', 'Rise above the water on jets with an instructor guiding you by radio. 15 minutes of flying.', 'After a short land briefing you put on the boots, helmet and vest. The instructor controls the jet ski power and talks to you through the helmet radio, so most people are flying within a few minutes.', 'Safety briefing on the beach
Gear up
15 minutes on the flyboard
Back to the beach', 'Flyboard session with instructor
Helmet, vest and wetsuit', 'Hotel transfer (optional add-on)
Video', 'Minimum age 14 and weight 45–110 kg.
Must be able to swim.', 'Water sports hut on the public beach, Sheraton Road.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000034', 'ar', 'جلسة فلاي بورد فوق البحر', 'ارتفع فوق الماء بالنفاثات بينما يوجّهك المدرب باللاسلكي. 15 دقيقة طيران.', 'بعد شرح قصير على الشاطئ تلبس الحذاء والخوذة والسترة. يتحكم المدرب في قوة الجت سكي ويتكلم معك من خلال لاسلكي الخوذة، فيطير أغلب الناس خلال دقائق.', 'شرح السلامة على الشاطئ
لبس المعدات
15 دقيقة على الفلاي بورد
العودة للشاطئ', 'جلسة فلاي بورد مع مدرب
خوذة وسترة وبدلة', 'التوصيل من الفندق (إضافة اختيارية)
الفيديو', 'الحد الأدنى للسن 14 عامًا والوزن من 45 إلى 110 كجم.
يجب أن تجيد السباحة.', 'كشك الرياضات المائية على الشاطئ العام، طريق الشيراتون.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000034', 'de', 'Flyboard-Session über dem Meer', 'Schweben Sie auf Wasserdüsen über dem Meer, während ein Instruktor Sie per Funk anleitet. 15 Minuten Flugzeit.', 'Nach einer kurzen Einweisung an Land ziehen Sie Schuhe, Helm und Weste an. Der Instruktor steuert die Leistung des Jetskis und spricht über das Helmfunkgerät mit Ihnen, sodass die meisten schon nach wenigen Minuten fliegen.', 'Sicherheitseinweisung am Strand
Ausrüstung anlegen
15 Minuten auf dem Flyboard
Zurück zum Strand', 'Flyboard-Session mit Instruktor
Helm, Weste und Neoprenanzug', 'Hoteltransfer (optional zubuchbar)
Video', 'Mindestalter 14 Jahre und Gewicht 45–110 kg.
Sie müssen schwimmen können.', 'Wassersporthütte am öffentlichen Strand, Sheraton Road.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000034', 'ru', 'Полёт на флайборде над морем', 'Поднимитесь над водой на реактивных струях, пока инструктор подсказывает вам по радио. 15 минут полёта.', 'После короткого инструктажа на берегу вы надеваете ботинки, шлем и жилет. Инструктор управляет мощностью гидроцикла и говорит с вами через радио в шлеме, поэтому большинство людей взлетают уже через несколько минут.', 'Инструктаж по безопасности на пляже
Экипировка
15 минут на флайборде
Возвращение на пляж', 'Полёт на флайборде с инструктором
Шлем, жилет и гидрокостюм', 'Трансфер из отеля (дополнительная опция)
Видео', 'Минимальный возраст — 14 лет, вес — 45–110 кг.
Необходимо уметь плавать.', 'Пункт водных видов спорта на городском пляже, улица Шератон.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000034', 'fr', 'Séance de flyboard au-dessus de la mer', 'Élevez-vous au-dessus de l’eau grâce à des jets, guidé par un moniteur par radio. 15 minutes de vol.', 'Après un court briefing à terre, vous enfilez les chaussures, le casque et le gilet. Le moniteur contrôle la puissance du jet-ski et vous parle via la radio du casque : la plupart des gens volent en quelques minutes.', 'Briefing sécurité sur la plage
Équipement
15 minutes de flyboard
Retour à la plage', 'Séance de flyboard avec moniteur
Casque, gilet et combinaison', 'Transfert depuis l’hôtel (option)
Vidéo', 'Âge minimum : 14 ans, poids entre 45 et 110 kg.
Savoir nager.', 'Cabane des sports nautiques sur la plage publique, Sheraton Road.', false, true);
