insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000035', 'en', 'Bedouin dinner and stargazing', 'Drive into the desert at sunset for bread baked on the fire, a Bedouin dinner and the stars.', 'A 4x4 takes you to a quiet camp in the desert hills. You watch the sunset, learn how Bedouin bread is baked on hot sand and stones, then share a dinner by the fire. After dinner the lights go down for the stars.', '16:30 pickup or meeting point
17:15 sunset in the desert
18:00 bread baking and tea
19:00 dinner by the fire
20:00 stargazing
20:45 back to Hurghada', '4x4 transfer to the camp
Dinner, tea and water
Stargazing with a guide', 'Hotel transfer (optional add-on)
Soft drinks at the camp', 'Bring a warm layer: desert nights are cool from November to March.', 'Safari base, Hurghada–Safaga road. Pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000035', 'ar', 'عشاء بدوي ومشاهدة النجوم', 'انطلق إلى الصحراء عند الغروب: خبز على النار وعشاء بدوي والنجوم.', 'سيارة دفع رباعي تأخذك إلى مخيم هادئ بين تلال الصحراء. تشاهد الغروب، وتتعلم كيف يُخبز الخبز البدوي على الرمل والحجارة الساخنة، ثم تتشارك العشاء حول النار. بعد العشاء تُطفأ الأنوار لمشاهدة النجوم.', '16:30 الاستلام أو نقطة اللقاء
17:15 الغروب في الصحراء
18:00 خبز البدو والشاي
19:00 العشاء حول النار
20:00 مشاهدة النجوم
20:45 العودة للغردقة', 'التوصيل بسيارة دفع رباعي للمخيم
عشاء وشاي ومياه
مشاهدة النجوم مع مرشد', 'التوصيل من الفندق (إضافة اختيارية)
المشروبات الغازية في المخيم', 'أحضر ملابس دافئة: ليالي الصحراء باردة من نوفمبر إلى مارس.', 'مقر السفاري على طريق الغردقة سفاجا. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000035', 'de', 'Beduinen-Abendessen und Sterne beobachten', 'Fahren Sie bei Sonnenuntergang in die Wüste – mit über dem Feuer gebackenem Brot, einem Beduinen-Abendessen und den Sternen.', 'Ein 4x4 bringt Sie zu einem ruhigen Camp in den Wüstenhügeln. Sie beobachten den Sonnenuntergang, erfahren, wie Beduinenbrot auf heißem Sand und Steinen gebacken wird, und essen dann gemeinsam am Feuer zu Abend. Nach dem Essen werden die Lichter für die Sterne gedimmt.', '16:30 Abholung oder Treffpunkt
17:15 Sonnenuntergang in der Wüste
18:00 Brotbacken und Tee
19:00 Abendessen am Feuer
20:00 Sterne beobachten
20:45 Rückfahrt nach Hurghada', '4x4-Transfer zum Camp
Abendessen, Tee und Wasser
Sterne beobachten mit Guide', 'Hoteltransfer (optional zubuchbar)
Softdrinks im Camp', 'Bringen Sie eine warme Schicht mit: Von November bis März sind die Wüstennächte kühl.', 'Safari-Basis, Straße Hurghada–Safaga. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000035', 'ru', 'Бедуинский ужин и звёздное небо', 'Поездка в пустыню на закате: хлеб, испечённый на огне, бедуинский ужин и звёзды.', 'Внедорожник 4x4 отвезёт вас в тихий лагерь среди пустынных холмов. Вы полюбуетесь закатом, узнаете, как бедуины пекут хлеб на горячем песке и камнях, а затем поужинаете у костра. После ужина свет приглушают, чтобы смотреть на звёзды.', '16:30 трансфер или место встречи
17:15 закат в пустыне
18:00 выпечка хлеба и чай
19:00 ужин у костра
20:00 наблюдение за звёздами
20:45 возвращение в Хургаду', 'Трансфер в лагерь на внедорожнике 4x4
Ужин, чай и вода
Наблюдение за звёздами с гидом', 'Трансфер из отеля (дополнительная опция)
Безалкогольные напитки в лагере', 'Возьмите тёплую одежду: с ноября по март ночи в пустыне прохладные.', 'База сафари, трасса Хургада — Сафага. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000035', 'fr', 'Dîner bédouin et observation des étoiles', 'Partez dans le désert au coucher du soleil pour du pain cuit au feu de bois, un dîner bédouin et les étoiles.', 'Un 4x4 vous emmène dans un camp paisible au milieu des collines du désert. Vous admirez le coucher du soleil, découvrez comment le pain bédouin est cuit sur le sable et les pierres brûlants, puis partagez un dîner autour du feu. Après le dîner, les lumières baissent pour laisser place aux étoiles.', '16:30 prise en charge ou point de rendez-vous
17:15 coucher de soleil dans le désert
18:00 cuisson du pain et thé
19:00 dîner autour du feu
20:00 observation des étoiles
20:45 retour à Hurghada', 'Transfert en 4x4 jusqu’au camp
Dîner, thé et eau
Observation des étoiles avec un guide', 'Transfert depuis l’hôtel (option)
Boissons sans alcool au camp', 'Prévoyez une couche chaude : les nuits dans le désert sont fraîches de novembre à mars.', 'Base safari, route Hurghada–Safaga. Localisation sur votre bon.', false, true);
