insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000037', 'en', 'Spa day pass with pool and massage', 'A full day of calm: pools, steam room, a 30-minute massage and a light lunch.', 'Spend the day at a quiet spa in Sahl Hasheesh. Use the indoor and outdoor pools, sauna and steam room as you like, enjoy a 30-minute relaxing massage at a time you choose, and have a light lunch by the pool.', '10:00 welcome drink
Pools, sauna and steam room
30-minute massage
Light lunch
16:00 end of the day', 'Spa access for the day
30-minute massage
Light lunch and water
Towels, robe and slippers', 'Hotel transfer (optional add-on)
Extra treatments', 'Minimum age 16.', 'Spa reception, Sahl Hasheesh old town. Pin on your voucher.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000037', 'ar', 'يوم كامل في السبا مع المسبح والمساج', 'يوم كامل من الهدوء: مسابح وغرفة بخار ومساج 30 دقيقة وغداء خفيف.', 'اقضِ اليوم في سبا هادئ في سهل حشيش. استخدم المسابح الداخلية والخارجية والساونا وغرفة البخار كما تحب، واستمتع بمساج استرخاء 30 دقيقة في الوقت الذي تختاره، وغداء خفيف بجوار المسبح.', '10:00 مشروب ترحيب
المسابح والساونا وغرفة البخار
مساج 30 دقيقة
غداء خفيف
16:00 نهاية اليوم', 'دخول السبا طوال اليوم
مساج 30 دقيقة
غداء خفيف ومياه
مناشف وروب وشبشب', 'التوصيل من الفندق (إضافة اختيارية)
جلسات إضافية', 'الحد الأدنى للسن 16 عامًا.', 'استقبال السبا، المدينة القديمة في سهل حشيش. الموقع في القسيمة.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000037', 'de', 'Spa-Tagespass mit Pool und Massage', 'Ein ganzer Tag voller Ruhe: Pools, Dampfbad, eine 30-minütige Massage und ein leichtes Mittagessen.', 'Verbringen Sie den Tag in einem ruhigen Spa in Sahl Hasheesh. Nutzen Sie Innen- und Außenpools, Sauna und Dampfbad ganz nach Belieben, genießen Sie zu einer Uhrzeit Ihrer Wahl eine 30-minütige Entspannungsmassage und essen Sie am Pool ein leichtes Mittagessen.', '10:00 Begrüßungsgetränk
Pools, Sauna und Dampfbad
30-minütige Massage
Leichtes Mittagessen
16:00 Ende des Tages', 'Spa-Zugang für den ganzen Tag
30-minütige Massage
Leichtes Mittagessen und Wasser
Handtücher, Bademantel und Hausschuhe', 'Hoteltransfer (optional zubuchbar)
Zusätzliche Anwendungen', 'Mindestalter 16 Jahre.', 'Spa-Rezeption, Altstadt von Sahl Hasheesh. Standort-Pin auf Ihrem Voucher.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000037', 'ru', 'Спа-день с бассейном и массажем', 'Целый день спокойствия: бассейны, парная, 30-минутный массаж и лёгкий обед.', 'Проведите день в тихом спа в Сахл-Хашише. Пользуйтесь крытым и открытым бассейнами, сауной и парной сколько захотите, насладитесь 30-минутным расслабляющим массажем в удобное для вас время и пообедайте у бассейна лёгкими блюдами.', '10:00 приветственный напиток
Бассейны, сауна и парная
30-минутный массаж
Лёгкий обед
16:00 окончание дня', 'Доступ в спа на весь день
30-минутный массаж
Лёгкий обед и вода
Полотенца, халат и тапочки', 'Трансфер из отеля (дополнительная опция)
Дополнительные процедуры', 'Минимальный возраст — 16 лет.', 'Ресепшен спа, старый город Сахл-Хашиша. Точка на карте — в вашем ваучере.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000037', 'fr', 'Journée spa avec piscine et massage', 'Une journée entière de calme : piscines, hammam, un massage de 30 minutes et un déjeuner léger.', 'Passez la journée dans un spa paisible de Sahl Hasheesh. Profitez à votre guise des piscines intérieure et extérieure, du sauna et du hammam, savourez un massage relaxant de 30 minutes à l’heure de votre choix et prenez un déjeuner léger au bord de la piscine.', '10:00 boisson de bienvenue
Piscines, sauna et hammam
Massage de 30 minutes
Déjeuner léger
16:00 fin de la journée', 'Accès au spa pour la journée
Massage de 30 minutes
Déjeuner léger et eau
Serviettes, peignoir et chaussons', 'Transfert depuis l’hôtel (option)
Soins supplémentaires', 'Âge minimum : 16 ans.', 'Accueil du spa, vieille ville de Sahl Hasheesh. Localisation sur votre bon.', false, true);
