insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000038', 'en', 'Private yacht day for your group', 'Your own yacht, captain and crew for six hours: choose the reefs and beaches you like.', 'Ideal for families and friends. The captain plans the day with you: snorkelling reefs, a quiet beach, or simply sun and swimming. Lunch is cooked on board.
Book per person, or the whole yacht for your group as a private trip.', '09:00 boarding at the marina
Your own plan with the captain
Lunch on board
15:00 back at the marina', 'Private yacht with captain and crew
Snorkelling gear
Lunch, water and soft drinks', 'Hotel transfer (optional add-on)
Marine park fee
Tips', 'Final route depends on wind and sea.', 'Hurghada New Marina, yacht pier B.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000038', 'ar', 'يوم على يخت خاص لمجموعتك', 'يختك الخاص مع الريّس والطاقم لست ساعات: اختار الشعاب والشواطئ اللي تحبها.', 'مثالي للعائلات والأصدقاء. يخطط الريّس اليوم معكم: شعاب للسنوركل، أو شاطئ هادئ، أو شمس وسباحة فقط. الغداء يُطبخ على اليخت.
احجز بالفرد، أو اليخت كاملًا لمجموعتك كرحلة خاصة.', '09:00 الصعود من المارينا
خطتكم الخاصة مع الريّس
غداء على اليخت
15:00 العودة للمارينا', 'يخت خاص مع الريّس والطاقم
معدات السنوركل
غداء ومياه ومشروبات', 'التوصيل من الفندق (إضافة اختيارية)
رسوم المحمية
الإكراميات', 'المسار النهائي يعتمد على الرياح والبحر.', 'مارينا الغردقة الجديدة، رصيف اليخوت B.', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000038', 'de', 'Privater Yachttag für Ihre Gruppe', 'Ihre eigene Yacht mit Kapitän und Crew für sechs Stunden: Wählen Sie die Riffe und Strände, die Ihnen gefallen.', 'Ideal für Familien und Freunde. Der Kapitän plant den Tag gemeinsam mit Ihnen: Schnorcheln an Riffen, ein ruhiger Strand oder einfach Sonne und Baden. Das Mittagessen wird an Bord gekocht.
Buchen Sie pro Person oder die ganze Yacht als privaten Ausflug für Ihre Gruppe.', '09:00 Einschiffen an der Marina
Ihr eigenes Programm mit dem Kapitän
Mittagessen an Bord
15:00 Zurück an der Marina', 'Private Yacht mit Kapitän und Crew
Schnorchelausrüstung
Mittagessen, Wasser und Softdrinks', 'Hoteltransfer (optional zubuchbar)
Meeresparkgebühr
Trinkgelder', 'Die endgültige Route hängt von Wind und Seegang ab.', 'Hurghada New Marina, Yachtsteg B.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000038', 'ru', 'День на частной яхте для вашей компании', 'Собственная яхта, капитан и команда на шесть часов: выбирайте рифы и пляжи, которые вам нравятся.', 'Идеально для семей и друзей. Капитан спланирует день вместе с вами: рифы для снорклинга, тихий пляж или просто солнце и купание. Обед готовят прямо на борту.
Бронируйте по количеству человек или всю яхту для вашей компании как частную поездку.', '09:00 посадка в марине
Ваша собственная программа вместе с капитаном
Обед на борту
15:00 возвращение в марину', 'Частная яхта с капитаном и командой
Снаряжение для снорклинга
Обед, вода и безалкогольные напитки', 'Трансфер из отеля (дополнительная опция)
Сбор морского парка
Чаевые', 'Окончательный маршрут зависит от ветра и состояния моря.', 'Новая марина Хургады, яхтенный причал B.', false, true);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed, machine_translated) values ('50000000-0000-0000-0000-000000000038', 'fr', 'Journée en yacht privé pour votre groupe', 'Votre propre yacht, avec capitaine et équipage, pendant six heures : choisissez les récifs et les plages qui vous plaisent.', 'Idéal pour les familles et les amis. Le capitaine organise la journée avec vous : récifs pour le snorkeling, plage tranquille ou simplement soleil et baignade. Le déjeuner est préparé à bord.
Réservez par personne, ou le yacht entier pour votre groupe en sortie privée.', '09:00 embarquement à la marina
Votre propre programme avec le capitaine
Déjeuner à bord
15:00 retour à la marina', 'Yacht privé avec capitaine et équipage
Équipement de snorkeling
Déjeuner, eau et boissons sans alcool', 'Transfert depuis l’hôtel (option)
Taxe du parc marin
Pourboires', 'L’itinéraire final dépend du vent et de la mer.', 'Hurghada New Marina, ponton des yachts B.', false, true);
